INSERT INTO `agenda` (`id`, `judul`, `slug`, `waktu`, `tanggal`, `tempat`, `gambar`, `deskripsi`, `created_at`) VALUES
(1, 'Kuliah Umum “Mindful Home: Hidup Berkesadaran Dimulai dari Rumah”', 'mindful-home-hidup-berkesadaran-di-rumah', '09:00:00', '2026-03-05', 'Gedung R, Lantai 2 FSRD Universitas Trisakti', 'image.png', 'DKV FSRD Universitas Trisakti in collaboration with Interior Design FSRD Universitas Trisakti presents:\r\n\r\nKULIAH UMUM\r\n“MINDFUL HOME: Hidup Berkesadaran Dimulai dari Rumah”\r\n\r\n🗣️ : Dr. Elda Franzia, M.Ds. dan Syafira Evita Sari\r\n📆 : Kamis, 5 Maret 2026\r\n⏰ : 09.00—12.00 WIB\r\n📍: Gedung R, lantai 2 FSRD USAKTI\r\n.\r\nPlease come and join us!\r\n\r\n*Khusus Dosen dan Mahasiswa FSRD USAKTI.\r\n*Tersedia Sertifikat.', '2026-03-02 00:00:00'),
(2, 'Enviro Up Skill – Pelatihan Life Cycle Asessment', 'enviro-up-skill-pelatihan-life-cycle-asessment', '13:00:00', '2026-03-08', '', '1776863321_6adc7b89aa98f9bf463e.png', '[BADAN PENGURUS HIMPUNAN MAHASISWAJURUSAN TEKNIK LINGKUNGAN UNIVERSITAS TRISAKTI PERIODE 2025/2026]\r\n\r\n🔊 Proudly Present 🔊\r\n\r\n♻️ ENVIRO UP SKILL – Pelatihan LCA (Life Cycle Assessment) ♻️\r\n\r\nDi tengah meningkatnya isu keberlanjutan dan tuntutan pengelolaan lingkungan yang lebih bertanggung jawab, metode Life Cycle Assessment (LCA) menjadi salah satu pendekatan penting untuk menganalisis dampak lingkungan dari suatu produk, proses, atau sistem secara menyeluruh, mulai dari tahap produksi hingga akhir siklus hidupnya.\r\n\r\nTapi kalian sudah memahami apa itu LCA dan bagaimana penerapannya dalam dunia teknik lingkungan dan industri atau belum nih?\r\n\r\nBPHMJTL Periode 2025/2026 menghadirkan Enviro Up Skill – Pelatihan LCA, sebuah kegiatan pengembangan kapasitas yang bertujuan untuk memberikan pemahaman mengenai konsep Life Cycle Assessment, tahapan analisis siklus hidup, serta aplikasinya dalam mendukung pengambilan keputusan berbasis sustainability.\r\n\r\nKegiatan akan dilaksanakan pada:\r\n🗓️Hari/tanggal : Minggu, 8 Maret 2026\r\n🕑Waktu : 13.00 – 16.00 WIB\r\n📍Tempat : Daring (Zoom Meeting Conference)\r\n\r\nBenefitsnya dari pelatihan ini apa aja sih? Jangan khawatir, untuk benefits yang didapatkan yaitu:\r\n✅ E-Sertifikat\r\n✅ Soft File Pemateri\r\n\r\n📝Registrasi melalui link berikut:\r\nhttps://bit.ly/daftarpelatihanLCA\r\n\r\n💰Biaya Pendaftaran:\r\nMahasiswa: Rp100.000,-\r\nMasyarakat Umum: Rp150.000,-\r\n\r\n💳Nomor Rekening Pembayaran:\r\nBNI\r\n1793805969\r\nAisyah Nisrina\r\n\r\nPelatihan ini terbuka untuk umum! Tingkatkan kompetensimu dalam memahami analisis siklus hidup sebagai bagian penting dari implementasi sustainability dan environmental assessment 🌱✨\r\n\r\n📞 Contact Us\r\nSARAH ROSYIDAH: +6285161718139\r\nAERO BINTANG: +6281289373546', '2026-04-22 13:08:41'),
(3, 'OKE Penerimaan Mahasiswa Baru Universitas Trisakti Periode Keenam', 'oke-penerimaan-mahasiswa-baru-universitas-trisakti-periode-keenam', '08:00:00', '2026-05-17', '', '1776875480_7e4396760ff923c293ef.png', 'OKE Universitas Trisakti kembali membuka Penerimaan Mahasiswa Baru untuk periode Keenam.\r\n\r\nCatat tanggalnya ya Bestri:\r\n\r\n🗓 16 – 17 Mei 2026\r\n⏰ Pukul 08:00 AM sampai selesai\r\n\r\nDaftarkan diri kamu sekarang juga melalui website PMB kita di\r\n\r\n🌐 https://spmb.trisakti.ac.id\r\n\r\nSelain jalur USM, kini kamu juga bisa melakukan pendaftaran melalui jalur PSSB (Rapor). Untuk informasi seputar pendaftaran mahasiswa baru bisa hubungi kami melalui\r\n\r\n📱 WhatsApp: 0877-7070-7703 atau 0882-1948-5675\r\n📩 Instagram DM: @pmb.usakti', '2026-04-22 16:31:20'),
(4, 'Glow Up Your Campus Look With Sariayu', 'glow-up-your-campus-look-with-sariayu', '09:00:00', '2026-04-22', 'Ruang Serbaguna KUIKK – Gedung E Lt. Dasar', '1776875535_fab95aebb69ce083a6d1.png', '✨ Glow Up Your Campus Look with Sariayu! ✨\r\n\r\nSiap tampil lebih fresh & percaya diri di kampus? 💁🏻‍♀️💙\r\nYuk ikutan event spesial bareng Sariayu yang bakal bikin kamu makin glowing dari dalam & luar!\r\n\r\n📍 Ruang Serbaguna KUIKK – Gedung E Lt. Dasar\r\n📅 Rabu, 22 April 2026\r\n⏰ 09.00 – 11.00 WIB – selesai\r\n\r\n💸 HTM: 50K\r\n🎁 Get products worth 180K!\r\n\r\n✨ Terbuka untuk dosen, tendik, dan mahasiswi\r\n⚠️ Kuota terbatas (30 peserta pertama!)\r\n\r\nJangan sampai ketinggalan kesempatan buat upgrade your campus look + dapetin insight beauty langsung dari ahlinya 💄🌿\r\n\r\n📲 Scan QR & register now!', '2026-04-22 16:32:15'),
(5, 'Festival Berkain Berkebaya', 'festival-berkain-berkebaya', '09:00:00', '2026-04-30', '', '1776875623_fe1ebd11e155f9b586ed.png', 'Festival Berkain Berkebaya\r\n\r\nkembali hadir dengan sentuhan modern yang memadukan budaya, gaya, dan kreativitas dalam satu rangkaian acara!\r\n\r\n✅ Workshop berkain untuk laki-laki & perempuan\r\n✅ Lomba karaoke berpasangan, tema “Berkain, Bernada, dan Berbudaya”\r\n\r\nYuk, pakai kainmu dan tunjukkan bakat terbaikmu dengan tetap melestarikan budaya Indonesia 🇮🇩\r\n\r\n🗓 Kamis, 30 April 2026\r\n⏰ 09.00 – 12.00 WIB\r\n📍 Auditorium FTI, Kampus A USAKTI\r\n\r\nDaftar sekarang dan jadi bagian dari pesona budaya masa kini!\r\nLink: https://berkain-usakti.carrd.co', '2026-04-22 16:33:43'),
(6, 'Webinar Magister Teknik Elektro Universitas Trisakti “Kecerdasan Artifisial sebagai Mitra Riset: Perspektif Praktisi tentang Peluang dan Integritas Akademik”', 'webinar-magister-teknik-elektro-universitas-trisakti-kecerdasan-artifisial-sebagai-mitra-riset-perspektif-praktisi-tentang-peluang-dan-integritas-akademik', '18:30:00', '2026-04-29', '', '1776875822_08bf57569f48c9ba670c.png', '✨ Webinar Magister Teknik Elektro Trisakti ✨\r\n\r\n📌 Tema: Kecerdasan Artifisial sebagai Mitra Riset: Perspektif Praktisi tentang Peluang dan Integritas Akademik\r\n🎙️ Narasumber: Dr. Arif Budiman, S.T., M.Si.\r\n(Enterprise Architect, Medco E&P Indonesia)\r\n\r\n🗓 Rabu, 29 April 2026\r\n⏰ 18.30 – 21.00 WIB\r\n📍 Online via Zoom Meeting\r\n\r\n🔗 Join via link: bit.ly/WebinarMTE_FTIUsakti\r\n📌 Meeting ID: 967 3783 1585\r\n📌 Passcode: 626045\r\n\r\nJangan lewatkan kesempatan untuk menambah wawasan seputar kecerdasan artificial sebagai mitra riset 🚀', '2026-04-22 16:37:02'),
(7, 'Company Visit 2026 to DAAI TV Indonesia', 'company-visit-2026-to-daai-tv-indonesia', '09:00:00', '2026-04-23', '', '1776875933_72d1e3c1a3deea395d1e.png', '🚀 READY TO EXPLORE THE FUTURE OF MEDIA? 🚀\r\n\r\nHello, Future Leaders! 🎓\r\n\r\nAre you curious about how the media industry survives and thrives in the era of TikTok, Instagram, and rapid digital disruption? It’s time to see it firsthand!\r\n\r\nWe are thrilled to invite you to the Company Visit 2026 to one of Indonesia’s most inspiring broadcasting stations: DAAI TV Indonesia! 📺✨\r\n\r\n[THEME]\r\n📌 “Media Industry Adaptation in Facing Competition from Digital Platforms and Social Media”\r\n\r\n🗓 Date: Thursday, April 23, 2026\r\n🕘 Time: 09:00 AM – 01:00 PM WIB\r\n📍 Location: DAAI TV Indonesia, PIK, North Jakarta\r\n\r\nBy joining this visit, you will get:\r\n✅ 15 Points of SKKE\r\n✅ E-Certificate\r\n✅ Valuable Knowledge & Networking\r\n✅ Free Registration Fee (Specifically for MM Students)\r\n\r\n[IMPORTANT REQUIREMENTS]\r\n🧥 Dress Code: MM Almamater Jacket is mandatory.\r\n👥 Quota: Limited to only 50 Students! (First come, first served).\r\n\r\n[REGISTRATION]\r\nDon’t miss out! Secure your spot before the deadline:\r\n⏳ Deadline: April 22, 2026\r\n🔗 Register Now: https://bit.ly/Registration_DAAITVIndonesia\r\n\r\nLet’s dive deep into the world of digital broadcasting and prepare ourselves for the shifting media landscape. See you at PIK!', '2026-04-22 16:38:53'),
(8, 'Podcast Pusat Karir “Breaking Into Banking: What You Need to Know Before Starting Your Career”', 'podcast-pusat-karir-breaking-into-banking-what-you-need-to-know-before-starting-your-career', '14:00:00', '2026-04-22', '', '1776875993_34cd351b7cbf6ca826dd.png', '🎙️ Mau terjun ke dunia perbankan tapi masih bingung mulai dari mana?\r\nYuk dengerin pengalaman langsung dari orang yang udah ada di industri ini! 🏦✨\r\nPodcast Pusat Karir hadir lagi dengan episode spesial:\r\n“Breaking Into Banking: What You Need to Know Before Starting Your Career”\r\n\r\nBersama:\r\n👩‍💼 Agnessa Britannia Paragina — Relationship Manager BRI Branch Office Cilangkap\r\n🎤 Host: Salim Budiman — Staff Pusat Karir Universitas Trisakti\r\n📅 Rabu, 22 April 2026\r\n⏰ 14.00 WIB\r\n▶️ Live di YouTube: Universitas Trisakti\r\n\r\nJangan sampai ketinggalan, set reminder sekarang! 🔔\r\n\r\n—————————————\r\nCAREER CENTER UNIVERSITAS TRISAKTI\r\nWebsite : pusatkarir.trisakti.ac.id\r\nInstagram : pusatkarirusakti\r\nLinkedIn : Career Center (CC) Trisakti\r\nTwitter : @CDC_Trisakti\r\nFacebook : PusatKarir Usakti\r\n(t) +62-21.566 3232 ext 8122', '2026-04-22 16:39:53'),
(9, 'Mini Seminar Continuing Dental Education Edisi Maret 2026', 'mini-seminar-continuing-dental-education-edisi-maret-2026', '10:00:00', '2026-03-12', 'Ruang Amphiteater FKG Usakti', '1776876130_c5c65a6ee9f5cd18a5d8.png', 'Mini Seminar Continuing Dental Education Edisi Maret 2026\r\n\r\nPEMBICARA : drg. Valdy Hartono, Sp.Perio\r\n\r\nTEMA : Digitally-guided Dentistry: Creating a Harmonious Smile\r\n\r\n🗓️Kamis, 12 Maret 2026\r\n⏰Pukul 10.00 – 11.30\r\n📍R. Amphiteater FKG Usakti', '2026-04-22 16:42:10'),
(10, 'Open Registration – Trisakti Business Law Fair IV 2026', 'open-registration-trisakti-business-law-fair-iv-2026', '23:59:00', '2026-05-07', '', '1776981458_bb0ca0b17900400d2b5c.png', '[OPEN REGISTRATION — TRISAKTI BUSINESS LAW FAIR IV 2026] ⚖️✨\r\n\r\nHello, Business Law Enthusiasts!\r\n\r\nIt is time to take a step further into the realm of business law.\r\nTrisakti Business Law Fair IV 2026 officially opens its registration for outstanding law students across Indonesia.\r\n\r\n📌 Competition Categories:\r\n1️⃣ Contract Drafting & Negotiation Competition\r\n2️⃣ Legal Opinion Competition\r\n\r\n🗓 Registration Period:\r\n16 April – 7 May 2026\r\n\r\n🔗 Registration Link:\r\nhttps://linktr.ee/TrisaktiBusinessLawFairIV\r\n\r\nDo not miss the opportunity to be part of a prestigious business law demonstrate your best capabilities.\r\n\r\nPrepare yourself. Take the stage. Leave your mark.\r\n\r\nMore information. 📱\r\nInstagram : @lawfair_tblc\r\nEmail : trisaktibusinesslawfair@gmail.com\r\n\r\nContact Person :\r\n0856-9401-7905 (Abel)\r\n0819-1133-6161 (Shareen)\r\n\r\n—\r\nTrisakti Business Law Community\r\nThinking Business, Practicing Law, Moving Forward Together', '2026-04-23 21:57:38');

