INSERT INTO `alumni` (`id`, `nama`, `foto_profil`, `background_images`, `jurusan`, `angkatan`, `deskripsi`, `updated_at`) VALUES
(1, 'Todotua Pasaribu', 'profil-1.png', 'bg-profil-1.png', 'Fakultas Teknologi Industri', '', 'Todotua Pasaribu dikenal memiliki latar belakang yang kuat di bidang Ekonomi karena berprofesi sebagai pengusaha. Todotua adalah mantan CEO Bomba Group, sebuah perusahaan holding investasi yang bergerak di sektor perkebunan, pertambangan, properti, energi serta kontraktor dan logistik. Berkat kepemimpinannya, perusahaan tersebut sukses memperluas jaringan bisnis dan berkontribusi terhadap pertumbuhan ekonomi lokal. Sebelum menjabat sebagai CEO Bomba Group, Todotua juga pernah menjabat sebagai Direktur PT. Thopas Artha Nauli sejak tahun 2016, Direktur PT. Chatura Indonesia pada tahun 2012, dan sebelumnya menjabat sebagai Operations Manager di PT. Jagad Energy pada 2005.\r\n\r\nTodotua aktif di dunia politik usai menjadi Wakil Ketua Tim Kampanye Nasional (TKN) untuk pasangan Prabowo Subianto dan Gibran Rakabuming Raka dalam Pemilihan Presiden 2024. Kini Todotua ditunjuk oleh Presiden terpilih, Prabowo Subianto sebagai Wakil Menteri Investasi dan Hilirisasi mendampingi Menteri Rosan Roeslani.', '2026-04-21 15:11:05'),
(2, 'Budi Gunawan', '1776763701_403def0a937327923351.png', NULL, 'Fakultas Ilmu Hukum', '', 'Lahir di Surakarta, 11 Desember 1959, Jenderal Polisi (Purn.) Prof. Dr. Budi Gunawan, S.H., M.Si., Ph.D. pernah menduduki sejumlah posisi penting di Kepolisian Republik Indonesia, seperti Kapolda Jambi dan Bali, Wakapolri hingga Kepala Badan Intelijen Negara (BIN) pada tahun 2016 hingga 2024. Beliau juga sempat menjadi Ajudan Presiden Megawati Soekarnoputri pada tahun 2001 hingga 2004.\r\n\r\nAlumni Program Doktor Ilmu Hukum Universitas Trisakti yang lulus dengan status SUMMA CUMLAUDE ini kini menduduki posisi sebagai Menteri Koordinator Bidang Politik dan Keamanan Republik Indonesia pada Kabinet Merah Putih periode 2024 – 2029. Budi Gunawan juga menjabat sebagai Ketua Umum PB E-Sports Indonesia periode 2020 hingga saat ini.', '2026-04-21 09:28:21'),
(3, 'Dudy Purwagandhi', '1776826010_c71ecf4c8cc7940d3c8b.png', '1776826010_8797e5bb1d9cf21f4cf1.png', 'Fakultas Hukum', '1995', 'DUDY PURWAGANDHI – MENTERI PERHUBUNGAN KABINET MERAH PUTIH PERIODE 2024-2029\r\n\r\nDudy Purwagandhi mengawali karir profesionalnya sebagai Staff of Assistant BOD di PT Tri Usaha Bhakti Truba (Holding) pada tahun 1997. Ia kemudian juga sempat menjadi Direktur PT Jhonlin Marine Trans serta Direktur PT Dua Samudera Perkasa dan Direktur Seacons Trading Limited di Singapura. Dudy pernah berkiprah di pemerintahan saat menjadi Staf Khusus Menteri Pemberdayagunaan Aparatur Negara dan Reformasi Birokrasi (Menpan-RB) pada tahun 2018-2019 dan Dewan Komisaris Perusahaan Listrik Negara (PLN) pada tahun 2020.\r\n\r\nKarir politik Dudy berawal ketika ditunjuk sebagai Wakil Bendahara Tim Kampanye Nasional (TKN) Koalisi Indonesia Maju pada Pemilihan Presiden (Pilpres) tahun 2019 lalu. Alumni Fakultas Hukum Universitas Trisakti angkatan 1995 ini kemudian dipilih oleh Presiden Prabowo Subianto sebagai Menteri Perhubungan di Kabinet Merah Putih periode 2024 – 2029.', '2026-04-22 02:46:50'),
(4, 'Silmy Karim', '1776826111_18a39ec2c7f01fcf3fef.png', '1776826111_9f27c678bb1b9bb932ba.jpg', 'Fakultas Ekonomi dan Bisnis', '1992', 'Silmy Karim memiliki pengalaman panjang selama lebih dari 20 tahun di berbagai perusahaan afiliasi maupun multinasional, seperti Komisaris Utama di PT Krakatau Posco, Komisaris Utama PT Krakatau Nippon Steel Synergy, Komisaris PT GE Power Solution Indonesia, Komisaris Utama di MAN Diesel & Turbo Indonesia, Advisor di PT Freeport Indonesia hingga Komisaris Independen Carrefour Indonesia, Direktur Utama Krakatau Steel (Persero) dan Dirjen Imigrasi Republik Indonesia.\r\n\r\nCukup banyak penghargaan yang pernah ia dapatkan antara lain Bintang Dharma Pertahanan dari Kementerian Pertahanan di tahun 2014, The Best CEO in Change Leadership dari Anugerah BUMN 2022, The Best CEO on Turnaround dari Anugerah BUMN tahun 2020, The Best CEO in Strategic Alliance dari Anugerah BUMN tahun 2018, The Best CEO in Steel Category dari The Iconomics pada 2021, dan Top CEO in Strategic Leadership dari Bisnis Indonesia pada 2021.\r\n\r\nTerkini, alumni Fakultas Ekonomi dan Bisnis Universitas Trisakti yang juga sekaligus Ketua Ikatan Alumni Trisakti sejak tahun 2022 lalu ini ditunjuk oleh Presiden Prabowo Subianto sebagai Wakil Menteri Imigrasi dan Pemasyarakatan Kementerian Hukum dan Hak Asasi Manusia.', '2026-04-22 02:48:31'),
(6, 'H. Maman Abdurrachman S.T.', '1776826593_c1eca8aa410122ca157b.jpg', '1776826593_295ddc2b7024d64ef018.png', 'Fakultas Teknologi Kebumian dan Energi', '2000', 'MENTERI USAHA KECIL DAN MENENGAH REPUBLIK INDONESIA 2024 – 2029\r\n\r\nMaman Abdurrachman mengawali kariernya di dunia politik dengan menjabat sebagai Anggota Dewan Perwakilan Rakyat (DPR) dari tahun 2018 hingga 2024 dari Fraksi Partai Golongan Karya (GOLKAR). Sebelum terjun ke dunia politik, Maman pernah bekerja sebagai Insinyur Lapangan di Premier Oil Indonesia serta Manajer Pengembangan Bisnis PT. Luas Biru Utama. Ia kemudian ditunjuk sebagai Tenaga Ahli Kementerian Sosial Republik Indonesia di tahun 2018.\r\n\r\nAlumni Fakultas Teknologi Kebumian dan Energi Universitas Trisakti angkatan tahun 2000 ini memang sudah dikenal aktif sejak kuliah. Maman Abdurrachman bahkan pernah menjabat Ketua Bidang HMI hingga Presiden Badan Eksekutif Mahasiswa Universitas Trisakti. Kini, Maman Abdurrachman dipercaya oleh Presiden Prabowo Subianto untuk menduduki posisi sebagai Menteri Usaha Kecil dan Menengah (UMKM) Republik Indonesia periode 2024-2029.', '2026-04-22 02:56:33'),
(7, 'Wibi Andrino, SH., MH', '1776826765_047b09738039d634ccb6.png', '1776826765_f6600da5cdfa03dd4fb3.png', 'Fakultas Hukum', '2005', 'Wibi Andrino SH., MH mengawali karirnya di dunia politik dengan bergabung bersama Partai Nasional Demokrat (NASDEM) dan aktif membantu warga dengan memberikan bantuan hukum gratis kepada warga Jakarta. Di tahun 2019, Wibi kemudian terpilih sebagai anggota DPRD DKI Jakarta dari Dapil 7.\r\n\r\nPada tahun 2024, lulusan Fakultas Hukum Universitas Trisakti ini kembali terpilih sebagai anggota DPRD DKI Jakarta. Tidak hanya itu, Ketua Bidang Hukum Ikatan Alumni (IKA) Universitas Trisakti juga dipercaya mengemban amanah sebagai Wakil Ketua DPRD DKI Jakarta periode 2024 – 2029.', '2026-04-22 02:59:25'),
(9, 'Rahma Landy', '1776981703_2d9ee203eed97a309f46.png', '1776981703_2bddafa3d7ac8a2e51ed.png', 'Fakultas Kedokteran Gigi', '2001', 'Pemilik nama lengkap Rahma Landy Sjahruddin adalah seorang model dan juga dokter gigi. Mengawali karirnya di industri hiburan tanah air sebagai juara ajang Wajah Femina pada tahun 2005, Rahma kemudian juga berhasil menjadi Runner Up 2 dan Puteri Indonesia Pariwisata di kompetisi Puteri Indonesia 2006. Rahma menjadi wakil Indonesia di ajang Miss International 2007 di Tokyo Jepang dan berhasil masuk 15 besar.\r\n\r\nSaat ini, lulusan Fakultas Kedokteran Gigi Universitas Trisakti angkatan tahun 2001 ini menjadi Dokter Gigi di Mayapada Hospital.', '2026-04-23 22:01:43'),
(10, 'Abcandra Muhammad Akbar Supratman', '1776981770_2498f2622da325eba309.png', '1776981770_77141c34a29da9d792cc.png', 'Fakultas Hukum', '2018', 'Abcandra Muhammad Akbar Supratman mengawali karirnya dengan menduduki jabatan sebagai Direktur di PT Celebes Elaeis Indonesia pada tahun 2017. Setahun kemudian ia ditunjuk sebagai Komisaris di PT Alat Kesehatan Indah Jaya. Ia kemudian beralih ke dunia politik dan berhasil melaju ke Senayan usai terpilih sebagai Anggota Dewan Perwakilan Daerah (DPD) dari Dapil Provinsi Sulawesi Tengah.\r\n\r\nTerkini, Abcandra resmi terpilih sebagai Wakil Ketua Majelis Permusyawaratan Rakyat (MPR) Republik Indonesia dari unsur DPD usai mengalahkan Fadel Muhammad dalam pemungutan suara (voting). Di usia 26 tahun, lulusan Fakultas Hukum Universitas Trisakti ini merupakan pimpinan MPR termuda saat ini.', '2026-04-23 22:02:50'),
(11, 'Prof. Dr. H. Amad Sudiro, S.H., M.H., M.Kn., M.M. ', '1776981871_01f0930201ec184c610c.jpg', '1776981871_2ee148dff08e0b6c443b.jpg', 'Fakultas Hukum', '1990', 'Prof. Dr. H. Amad Sudiro, S.H., M.H., M.Kn., M.M. adalah seorang dosen Ilmu Hukum sekaligus praktisi hukum (Advokat dan Arbiter) dan menjabat sebagai pimpinan di sejumlah lembaga / badan, dan organisasi profesi hukum seperti Ketua Umum Dewan Pimpinan Nasional Asosiasi Profesi Hukum Indonesia (DPN-APHI), Ketua Badan Arbitrase dan Alternatif Penyelesaian Sengketa Konstruksi Indonesia (BADAPSKI), serta Penasehat Asosiasi Pimpinan Perguruan Tinggi Hukum Indonesia (APPTHI), dan Pembina Dewan Pimpinan Pusat Asosiasi Doktor Hukum Indonesia (DPP-ADHI).\r\n\r\nSaat ini, alumni Fakultas Hukum Universitas Trisakti tahun 1990 ini dipercaya sebagai Rektor Universitas Tarumanagara untuk periode 2024 – 2028.', '2026-04-23 22:04:31'),
(12, 'OKE Ustadz Yusuf Mansur', '1776981950_8d1547c4011c557ae310.jpg', '1776981950_bc76d6adec6b0a8b9e0e.jpg', 'OKE Fakultas Ekonomi dan Bisnis', '2019', 'OKE Pemilik nama asli H. Jam’an Nurchotib Mansur atau yang akrab dikenal dengan nama Yusuf Mansur adalah seorang pedakwah Islam yang sangat populer di Indonesia. Selain menjadi seorang pedakwah, Ustadz Yusuf Mansur juga merupakan seorang penulis, dan pengusaha. Beberapa bidang usaha yang ia geluti antara lain Paytren hingga restoran cepat saji. Kini, lulusan Program Doktor Ilmu Ekonomi Universitas Trisakti ini juga menggeluti dunia politik dengan menjabat sebagai Ketua Umum Bidang Ekonomi Ummat dan Syariah dari Partai Perindo.', '2026-04-24 02:44:34'),
(13, 'Ariyo Wahab', '1776982064_df0ee76994a8600648dc.png', '1776982064_f11e5e7d7eaf196b9b72.png', 'Fakultas Hukum', '1992', 'Ariyo Wahab mengawali karirnya di dunia entertainment sebagai vokalis band Kampus, 24 Hours (1992-1996) bersama Freddy (Gitar), Bango (Bass), dan Ai (Drum). Ariyo sempat bergabung dengan grup band Ungu, menjadi solois hingga akhirnya lulusan Fakultas Hukum angkatan tahun 1992 Universitas Trisakti ini bersama Pongki Barata, Nugie dan Baim membentuk sebuah band ‘The Dance Company’ yang masih eksis hingga saat ini', '2026-04-23 22:07:44');

