CREATE TABLE `berita` (
  `id` int(10) UNSIGNED NOT NULL,
  `judul` varchar(255) NOT NULL,
  `tanggal` date NOT NULL,
  `gambar` varchar(255) DEFAULT NULL,
  `deskripsi` text DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `slug` varchar(255) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Dumping data for table `berita`
--

INSERT INTO `berita` (`id`, `judul`, `tanggal`, `gambar`, `deskripsi`, `created_at`, `updated_at`, `slug`) VALUES
(1, 'Penawaran Kerja Sama Kemitraan Merchant Platform UI Solution', '2026-04-14', 'berita-1.jpeg', 'Pada hari Senin, 13 April 2026, Unit Kerja Khusus Science Techno Park UI yang diwakili oleh: Suminto B. Ak., S.Sos., M.Si (Kepala Divisi Operasional); Nabila Ashriyanti, S.I.Kom (Marketing Corporate); Chandra Salim, S.T (Marketing Corporate); Paskal Rachman, S.T, M.T (Koordinator Layanan) mempresentasikan Platform UI Solution dan diskusi Kemitraan Strategis di LPPM, Universitas Trisakti (Usakti) dalam rangka penawaran kerjasama untuk memajukan industri berbasis riset dan teknologi di Indonesia.\r\n\r\nUI menawarkan Usakti untuk berperan aktif dalam mengisi dan memanfaatkan fasilitas yang terdapat dalam platform UI Solution di bawah bingkai kerjasama yang saling menguntungkan. Peralatan dan ruangan riset Usakti yang memenuhi standar peruntukannya dapat mengisi etalase yang tersedia di UI Solution.\r\n\r\nKegiatan tersebut dihadiri oleh Prof. Dr. Ir. Astri Rinanti, M.T., IPM., ASEAN Eng. (Direktur LPPM Usakti), Dr. Ir. Winnie Septiani, S.T., M.Si., IPM (WaDir Penelitian LPPM), Dr. Erni Erfan, S.Pd., M.Biomed. (KaPus. Inovasi dan Sumber Daya IPTEKS), Dr. Cama Juli Rianingrum, S.Sn., M.Si. (KaPus. Peningkatan Kapasitas SDM), para WD 1 dan Kepala Pelaksana Harian Dewan Riset dan Pengabdian Masyarakat Fakultas DRPMF dari delapan fakultas (FH, FEB, FK, FKG, FTSP, FTKE, FALTL, dan FSRD) di Usakti, selain itu hadir juga oleh Endang Djuana, ST, M.Eng, Ph.D (KaPus Kecerdasan Artifisial dan Teknologi Maju) beserta anggota dan Dr. Eng. Ersan Yudhapratama Muslih, S.Si., M.Sc.Eng. (KaPus Energi dan Material Berkelanjutan) dan anggota.', '2026-04-17 01:10:55', '2026-04-19 05:46:22', 'penawaran-kerja-sama-kemitraan-merchant-platform-ui-solution'),
(2, 'Seminar 99% Abstraksi: The Voice of The Village – Eko Nugroho', '2026-04-14', 'berita-2.jpg', 'Jakarta – Program Studi Arsitektur FTSP Universitas Trisakti berkolaborasi dengan Omah Library menggelar seminar 99% Abstraksi: The Voice of The Village – Eko Prawoto pada 14 April 2026 di Auditorium Lantai 9, Kampus A Universitas Trisakti, secara hybrid dan gratis untuk umum.\r\n\r\nKegiatan ini dibuka oleh Sekretaris Program Studi Arsitektur FTSP, Ar. Arief Fadhilah, S.T., M.T., yang menekankan pentingnya memahami arsitektur sebagai refleksi nilai sosial dan budaya, disamping sebagai keterampilan teknis. Sambutan turut disampaikan oleh perwakilan Yayasan Eko Prawoto, Ibu Rinawati (istri alm. Eko Prawoto sekaligus pendiri Yayasan Eko Prawoto), yang berharap pemikiran Eko Prawoto terus menginspirasi generasi muda.\r\n\r\nHadir sebagai narasumber sekaligus penulis buku, Ar. Realrich Sjarief dan Hanifah Sausan Nurfinaputri dari Omah Library, yang membahas karya serta gagasan Eko Prawoto melalui buku The Voice of The Village. Diskusi juga menghadirkan penanggap Tulus Widiarso dan Ardilla Jefri Karista yang menyampaikan perspektif akademis dan kebutuhan pendekatan keilmuan arsitektur.\r\n\r\nKegiatan ini diharapkan dapat memperluas wawasan peserta mengenai arsitektur yang humanis, kontekstual, dan berakar pada nilai lokal.', '2026-04-17 01:10:55', '2026-04-19 05:46:59', 'seminar-99-abstraksi-the-voice-of-the-village-eko-nugroho'),
(3, 'Ferry Irwandi di Universitas Trisakti: Produktivitas Anak Muda Jadi Kunci Indonesia Emas 2045', '2026-04-14', 'berita-3.png', 'Jakarta — Universitas Trisakti menghadirkan kreator konten edukatif Ferry Irwandi dalam Eurasia Foundation–Universitas Trisakti International Lecture Series bertema Strengthening Sociotechnopreneurship in the Eurasia Community di Kampus A Universitas Trisakti, Jakarta, Jumat (10/4).\r\n\r\nDalam kuliah umum tersebut, Ferry membahas isu strategis yang dinilai akan menentukan masa depan Indonesia, mulai dari produktivitas, pertumbuhan ekonomi, GDP, pendapatan per kapita, bonus demografi, hingga visi Indonesia Emas 2045. Di hadapan mahasiswa lintas fakultas, ia menegaskan bahwa bonus demografi tidak otomatis menjadi kekuatan jika tidak dibarengi peningkatan kualitas sumber daya manusia dan produktivitas.\r\n\r\nMenurut Ferry, generasi muda harus melampaui peran sebagai pengguna teknologi. Anak muda, kata dia, perlu menjadi pencipta solusi yang mampu menghasilkan nilai tambah bagi perekonomian sekaligus menjawab persoalan sosial di masyarakat.\r\n\r\n“Menjadi technopreneur saja tidak cukup. Kita perlu menambahkan nilai sosial dalam setiap inovasi yang kita bangun, agar dampaknya bisa lebih luas dan berkelanjutan,” ujar Ferry.\r\n\r\nPaparan Ferry mendapat respons antusias dari peserta. Diskusi berlangsung interaktif, dengan mahasiswa menyoroti keterkaitan antara produktivitas, inovasi, dan peran generasi muda dalam mendorong pertumbuhan ekonomi nasional. Materi yang disampaikan membuat forum ini tidak hanya inspiratif, tetapi juga relevan dengan tantangan nyata yang akan dihadapi Indonesia ke depan.\r\n\r\nKegiatan ini sekaligus menegaskan komitmen Universitas Trisakti dalam menyiapkan mahasiswa yang tidak hanya unggul secara akademik, tetapi juga kritis, adaptif, dan memiliki kepedulian sosial. Melalui forum internasional seperti ini, Trisakti terus memperkuat perannya sebagai kampus yang mendorong lahirnya sociotechnopreneur muda berdaya saing global.', '2026-04-17 01:10:55', '2026-04-19 05:49:10', 'ferry-irwandi-di-universitas-trisakti-produktivitas-anak-muda-jadi-kunci-indonesia-emas-2045'),
(4, 'Dosen Universitas Trisakti Ubah Jelantah Jadi Lilin Aromatik', '2026-04-13', 'berita-4.png', 'Rakyat Merdeka – Tim Pengabdian kepada Masyarakat (PKM) internasional dari Universitas Trisakti menggelar pelatihan bertajuk Making Aromatherapy Candles from Waste Cooking Oil for Futajima Shimin Centre Community, di Futajima Shimin Centre, Kitakyushu, Jepang.\r\n\r\nSumber berita: https://rm.id/baca-berita/education/307137/dosen-universitas-trisakti-ubah-jelantah-jadi-lilin-aromaterapi-di-jepang', '2026-04-17 01:10:55', '2026-04-19 05:50:08', 'dosen-universitas-trisakti-ubah-jelantah-jadi-lilin-aromatik'),
(5, 'Inovasi Circular Water System Universitas Trisakti Diterapkan di Masjid Jepang', '2026-04-13', 'berita-5.png', 'Rakyat Merdeka – Air bekas wudhu yang selama ini terbuang ternyata memiliki potensi besar untuk dimanfaatkan kembali. Berangkat dari kondisi tersebut, Lembaga Penelitian dan Pengabdian kepada Masyarakat Universitas Trisakti (LPPM) Universitas Trisakti melaksanakan program Pengabdian kepada Masyarakat (PKM) internasional di Kitakyushu Islamic Cultural Centre (KICC), Jepang, Sabtu (11/4/2026).\r\n\r\nSumber berita: https://rm.id/baca-berita/education/307136/inovasi-circular-water-system-universitas-trisakti-diterapkan-di-masjid-jepang', '2026-04-17 01:10:55', '2026-04-19 05:52:12', 'inovasi-circular-water-system-universitas-trisakti-diterapkan-di-masjid-jepang'),
(9, 'Diseminasi Hasil Tracer Study 2025 dan Launching Tracer Study 2026 Universitas Trisakti Berlangsung Meriah', '2026-04-17', 'berita-6.png', 'Jakarta, 15 April 2026 — Universitas Trisakti sukses menyelenggarakan kegiatan Diseminasi Hasil Tracer Study 2025 sekaligus Launching Tracer Study 2026 yang bertempat di Ruang Seminar Lantai 12, Kampus A. Acara ini berlangsung dengan penuh antusiasme dan dihadiri oleh jajaran pimpinan universitas serta sivitas akademika.\r\n\r\nKegiatan ini turut dihadiri oleh Wakil Rektor I Dr. Ir. Muhammad Burhannudinnur, M.Sc., IPU, ASEAN Eng. dan Wakil Rektor III Ir. Yoska Oktaviano, MT, para dekan, wakil dekan, dosen, serta tenaga kependidikan di lingkungan universitas. Kehadiran para pemangku kepentingan ini menunjukkan komitmen bersama dalam meningkatkan kualitas lulusan melalui evaluasi berkelanjutan.\r\n\r\nAcara dibuka dengan pemaparan hasil Tracer Study 2025 oleh Kepala Pusat Karir Universitas Trisakti Richy Wijaya W., SE., MM., C.R.A., C.R.P, Dalam paparannya disampaikan berbagai temuan penting terkait profil lulusan, kesesuaian bidang kerja, waktu tunggu memperoleh pekerjaan, hingga masukan dari pengguna lulusan. Hasil ini menjadi dasar strategis dalam pengembangan kurikulum dan peningkatan daya saing lulusan di dunia kerja.\r\n\r\nSebagai bentuk apresiasi atas kinerja fakultas dalam mendukung pelaksanaan tracer study, acara dilanjutkan dengan pemberian penghargaan prestasi kepada fakultas-fakultas yang menunjukkan capaian terbaik. Momen ini disambut hangat oleh para peserta dan menjadi motivasi untuk terus meningkatkan kontribusi di masa mendatang.\r\n\r\nKategori prodi yg telah mencapai 80% untuk Gross Response Rate & Completion Rate sebanyak 24 Prodi, terdiri dari:\r\n\r\n- D3 Akuntansi Sektor Publik\r\n⁠- S1 Ekonomi Pembangunan\r\n⁠- Magister Manajemen\r\n- ⁠Pendidikan Kedokteran\r\n⁠- Pendidikan Dokter Gigi\r\n⁠- Profesi Dokter Gigi\r\n⁠- Magister Ilmu Kedokteran Gigi\r\n⁠- Spesialis Konservasi Gigi\r\n⁠- Teknik Sipil\r\n⁠- Arsitektur\r\n⁠- Magister Teknik Sipil\r\n⁠- Magister Arsitektur\r\n⁠- Teknik Elektro\r\n⁠- Magister Teknik Mesin\r\n⁠- Magister Teknik Elektro\r\n- ⁠Teknik Perminyakan\r\n⁠- Teknik Geologi\r\n⁠- Magister Teknik Perminyakan\r\n⁠- Arsitektur Lanskap\r\n- ⁠Desain Interior\r\n⁠- Desain Produk\r\n⁠- DKV\r\n⁠- Fotografi\r\n⁠- Magister Desain Produk\r\nKategori Fakultas yg telah mencapai 80% untuk Gross Respon Rate & Completion Rate sebanyak 3 Fakultas, terdiri:\r\n\r\n- Fakultas Kedokteran Gigi\r\n⁠- Fakultas Teknik Sipil dan Perencanaan\r\n⁠- Fakultas Teknologi Kebumian dan Energi\r\n⁠- Fakultas Seni Rupa dan Desain\r\n\r\nRangkaian kegiatan kemudian berlanjut dengan sambutan dari Wakil Rektor III Universitas Trisakti. Dalam sambutannya, beliau menekankan pentingnya tracer study sebagai instrumen evaluasi mutu pendidikan tinggi yang berbasis data dan relevansi industri.\r\n\r\nPuncak acara ditandai dengan peresmian Launching Tracer Study 2026 oleh Wakil Rektor III. Dengan diluncurkannya tracer study terbaru ini, Universitas Trisakti berharap dapat memperoleh data yang lebih komprehensif dan akurat guna mendukung peningkatan kualitas pendidikan serta memperkuat hubungan dengan alumni dan dunia industri.\r\n\r\nKegiatan ini menjadi langkah nyata Universitas Trisakti dalam menjaga kualitas lulusan dan memastikan relevansi pendidikan dengan kebutuhan zaman.', '2026-04-17 01:10:55', '2026-04-19 05:45:52', 'diseminasi-hasil-tracer-study-2025-dan-launching-tracer-study-2026-universitas-trisakti-berlangsung-meriah'),
(12, 'USAKTI EXPO 2026: Ajang Promosi Pendidikan Universitas Trisakti', '2026-04-18', '1776577991_b83b9f4419dcab09f1e8.jpeg', 'Jakarta, 18 April 2026 – Universitas Trisakti melalui UPT Promosi dan Admisi menyelenggarakan Usakti Expo 2026 pada 17–18 April 2026 di Gelanggang Mahasiswa Universitas Trisakti. Kegiatan ini menjadi ajang promosi pendidikan bagi calon mahasiswa untuk mengenal lebih dekat program unggulan yang ditawarkan.\r\n\r\nAcara secara resmi dibuka oleh Rektor Universitas Trisakti, Prof. Dr. Ir. Kadarsah Suryadi, DEA, yang dalam sambutannya menekankan pentingnya pendidikan tinggi dalam mencetak generasi unggul dan berdaya saing. Pembukaan ini turut didampingi oleh Prof. Dr. drg. Tri Erri Astoeti, M.Kes selaku Wakil Rektor IV Universitas Trisakti, Denon Prawiraatmaja selaku Bendahara Ikatan Alumni Trisakti yang mewakili Ketua Ikatan Alumni Trisakti, Maman Abdurrahman, Menteri UMKM Republik Indonesia, serta Debbie Kemalasari, S.T., M.B.A., M.T., I.P.M selaku Kepala UPT Promosi dan Admisi Universitas Trisakti.\r\n\r\nSeluruh fakultas di Universitas Trisakti turut berpartisipasi dengan menghadirkan booth interaktif yang menampilkan informasi program studi, fasilitas, hingga prospek karier. Selain itu, kegiatan ini juga melibatkan satuan pendidikan di bawah Yayasan Trisakti, yaitu Sekolah Tinggi Manajemen Asuransi Trisakti, Institut Pariwisata Trisakti, dan Institut Transportasi Logistik Trisakti.\r\n\r\nUsakti Expo 2026 disambut antusias oleh para pengunjung dari kalangan pelajar dan masyarakat umum yang memanfaatkan kesempatan ini untuk mendapatkan informasi langsung seputar dunia perkuliahan.\r\n\r\nMelalui kegiatan ini, Universitas Trisakti terus menunjukkan komitmennya dalam memberikan akses informasi pendidikan yang luas dan berkualitas bagi generasi muda.', '2026-04-19 05:53:11', '2026-04-19 05:53:11', 'usakti-expo-2026-ajang-promosi-pendidikan-universitas-trisakti'),
(13, 'Kunjungan Delegasi Universitas Trisakti ke Australia: Penguatan Kolaborasi Strategis dengan Universitas Terkemuka', '2026-04-17', '1776578162_efedfb775d1b04eb407f.jpeg', 'Delegasi Universitas Trisakti melaksanakan kunjungan kerja ke University Adelaide dan Flinders University pada tanggal 14 April 2026 sebagai bagian dari upaya memperkuat kerja sama internasional di bidang pendidikan tinggi.\r\n\r\nDelegasi Universitas Trisakti terdiri dari:\r\n\r\n- Professor Dr. Tri Erri Astoeti (Wakil Rektor)\r\n- Agus Guntoro, Ph.D (Direktur Kantor Urusan Internasional, Kerja Sama, dan Kebudayaan)\r\n- Amalia Zuhra, Ph.D (Kepala Urusan Internasional)\r\n- Agustin R. Lakawa, Ph.D (Kepala Unit Kebudayaan)\r\n\r\nKunjungan ke University Adelaide pada 14 April 2026 diawali dengan campus tour, dilanjutkan dengan welcome meeting bersama jajaran Global Partnerships dan International Recruitment, serta roundtable meeting yang menghadirkan pimpinan fakultas internasional. Diskusi berfokus pada pengenalan institusi, pemaparan program internasional, serta eksplorasi peluang kolaborasi strategis antar kedua universitas.\r\n\r\nSelanjutnya, delegasi melaksanakan kunjungan ke Flinders University dengan agenda utama roundtable meeting dan campus tour. Pertemuan ini membahas secara konkret potensi kerja sama, meliputi pengembangan dual degree programs, joint research, joint publications, joint teaching initiatives, guest lectures, serta cultural exchange activities.\r\n\r\nKegiatan ini mencerminkan komitmen Universitas Trisakti dalam memperluas jejaring global dan meningkatkan kualitas pendidikan melalui kolaborasi internasional yang berkelanjutan. Diharapkan, hasil dari kunjungan ini dapat segera ditindaklanjuti dalam bentuk program nyata yang memberikan dampak positif bagi sivitas akademika kedua institusi.', '2026-04-19 05:56:02', '2026-04-19 05:56:02', 'kunjungan-delegasi-universitas-trisakti-ke-australia-penguatan-kolaborasi-strategis-dengan-universitas-terkemuka'),
(14, 'Universitas Trisakti Laksanakan PKM Eco-Masjid di Jepang, Wudhu Lebih Efisien', '2026-04-13', '1776578246_e98854cbcdf7daefe903.png', 'Rakyat Merdeka – Tim Lembaga Penelitian dan Pengabdian kepada Masyarakat (LPPM) Universitas Trisakti melaksanakan program Pengabdian kepada Masyarakat (PKM) internasional bertajuk Community-Driven Solutions for Sustainable Ablution Water Management Supporting Eco-Mosque Practices, di Kitakyushu, Jepang, Sabtu (11/4/2026).\r\n\r\nSumber Berita: https://rm.id/baca-berita/education/307134/universitas-trisakti-laksanakan-pkm-ecomasjid-di-jepang-wudhu-lebih-efisien', '2026-04-19 05:57:26', '2026-04-19 05:57:26', 'universitas-trisakti-laksanakan-pkm-eco-masjid-di-jepang-wudhu-lebih-efisien'),
(15, 'Purnabakti Trisakti Bersatu dalam Hangatnya HalalBiHalal di Karawaci Tangerang', '2026-04-11', '1776738237_3842d773aeb8f192828b.jpeg', 'Dalam rangka mempererat tali silaturahim antar sesama keluarga besar Purnabakti Trisakti, telah diselenggarakan acara HalalBiHalal Purnabakti Trisakti dengan tema “Jalin Silaturahim, Maknai Kebersamaan”. Kegiatan ini pada hari Sabtu, 11 April 2026 bertempat di Le Semar Hotel Karawaci, Tangerang.\r\n\r\nAcara diawali dengan menyanyikan lagu kebangsaan Indonesia Raya secara bersama-sama. Nuansa religius terasa saat pembacaan ayat suci Al-Quran oleh Ustaz Dedi Junaedi, S.E., M.M.\r\n\r\nSuasana semakin hangat dengan sambutan dari Ketua Purnabakti Trisakti, Bapak Heru Purwanto, S.E., M.H., yang menyampaikan pentingnya menjaga silaturahim sebagai bagian dari warisan nilai Trisakti. Sambutan juga disampaikan oleh Penasehat Purnabakti, Bapak Sakwad Edy Kusuma, S.H., M.H., yang menekankan peran para purnabakti dalam tetap mendukung nilai-nilai luhur yang telah dibangun bersama, selanjutnya kesan dan pesan disampaikan oleh perwakilan purnabakti trisakti Dra. Evianti E. Ruslan.\r\n\r\nKegiatan berlanjut dengan penyampaian hikmah HalalBiHalal dan doa yang dipimpin oleh Bapak Subagia Muchtar, S.H., M.H. Momentum ini menjadi momen reflektif bagi seluruh hadirin untuk saling memaafkan dan mempererat ikatan persaudaraan.\r\n\r\nSelanjutnya, hadirin disuguhkan penayangan video perjalanan Purnabakti Trisakti yang menggugah rasa bangga dan nostalgia. Dilanjutkan dengan sesi salam-salaman dan foto bersama, diiringi lagu religi Lebaran yang menambah keakraban antar peserta.\r\n\r\nAcara ini diharapkan menjadi pemantik semangat bagi keluarga besar Purnabakti Trisakti untuk terus menjaga silaturahim, saling mendukung, dan terus memberikan kontribusi positif bagi Universitas Trisakti.', '2026-04-21 02:23:57', '2026-04-21 02:23:57', 'purnabakti-trisakti-bersatu-dalam-hangatnya-halalbihalal-di-karawaci-tangerang'),
(16, 'Workshop Spesial untuk Mahasiswi Universitas Trisakti', '2026-04-22', '1776917022_0c773c9b8f455ba9eb44.jpeg', 'Halo, Girls!! 💖\r\n\r\nDalam rangka memperingati Hari Kartini & bulan literasi finansial, Let’s Invest Girls berkolaborasi dengan Universitas Trisakti (Kantor Urusan Internasional, Kerjasama, dan Kebudayaan) dan Int’l Association of Business Communicators (IABC Indonesia Chapter) menghadirkan workshop spesial untuk mahasiswi Trisakti 💫\r\n\r\nDi sini, kita akan belajar:\r\n\r\nCara mengelola keuangan biar nggak cepat habis, tapi justru berkembang\r\n⁠Skill komunikasi yang lebih impactful\r\n⁠Leadership mindset untuk jadi perempuan yang tangguh & independen\r\nNggak cuma itu, girls—akan ada:\r\n🎁 Goodie bag\r\n📜 E-certificate, materi presentasi (soft file) & e-book\r\n🎉 Kuis, games, dan doorprize menarik!\r\n\r\n📅 Jumat, 30 April 2026\r\n⏰ 13.30 – 17.00 WIB\r\n📍 Universitas Trisakti\r\nRuang Serbaguna KUIKK, Gedung E, Lantai Dasar\r\n\r\n🔔Limited seats, by registration only\r\nhttps://tinyurl.com/PowerfromWithin\r\n\r\nYuk girls, jangan sampai ketinggalan—daftar sekarang dan mulai perjalananmu jadi perempuan yang lebih percaya diri secara finansial dan personal 💖\r\n\r\n#LetsInvestGirls #GirlsEmpowerment #IABCIndonesia #KUIKKTrisakti #Trisakti', '2026-04-23 04:03:42', '2026-04-23 04:03:42', 'workshop-spesial-untuk-mahasiswi-universitas-trisakti'),
(17, 'Mahasiswa DKV Universitas Trisakti Gelar KKL di Yogyakarta, Perkuat Koneksi Industri Kreatif', '2026-04-23', '1776980964_7bcc1420a8771a32ec6a.jpeg', 'Yogyakarta, 23 April 2026 — Program Studi Desain Komunikasi Visual (DKV) Universitas Trisakti sukses menyelenggarakan kegiatan Kuliah Kerja Lapangan (KKL) di Yogyakarta pada 20–23 April 2026. Kegiatan ini menjadi bagian dari upaya akademik untuk menjembatani teori yang diperoleh mahasiswa di kelas dengan praktik langsung di lapangan.\r\n\r\nKKL kali ini melibatkan mahasiswa DKV dalam serangkaian kunjungan ke berbagai titik strategis industri kreatif dan budaya di Yogyakarta, mulai dari institusi pendidikan seni hingga sentra kerajinan dan objek wisata budaya. Kota Yogyakarta dipilih karena dikenal sebagai pusat seni, budaya, sekaligus ekosistem kreatif yang berkembang pesat di Indonesia.\r\n\r\nSelama empat hari pelaksanaan, mahasiswa melakukan observasi langsung, wawancara dengan praktisi, serta dokumentasi visual sebagai bagian dari metode pembelajaran berbasis pengalaman. Beberapa lokasi yang dikunjungi antara lain Institut Seni Indonesia (ISI) Yogyakarta untuk studi akademis, Candi Prambanan untuk eksplorasi fotografi arsitektur dan budaya, serta Kasongan sebagai sentra kerajinan keramik. Selain itu, mahasiswa juga mempelajari strategi branding lokal melalui kunjungan ke Kopi Tempuran.\r\n\r\nKetua pelaksana sekaligus Kaprodi DKV Bambang Tri Wardoyo,SSn,MDs menyampaikan bahwa KKL ini tidak hanya bertujuan meningkatkan wawasan mahasiswa terhadap industri kreatif, tetapi juga melatih kemampuan analisis, komunikasi, serta membangun jejaring profesional. “Mahasiswa diharapkan mampu memahami realitas industri sekaligus mengembangkan kepekaan terhadap budaya visual lokal,” ujarnya.\r\n\r\nKegiatan ini turut didampingi oleh dosen pembimbing lapangan serta melibatkan berbagai pihak sebagai narasumber, mulai dari akademisi, pelaku industri kreatif, hingga seniman lokal. Pendekatan partisipatif dan observasional menjadi metode utama dalam pelaksanaan KKL, sehingga mahasiswa dapat terlibat langsung dalam proses kreatif di lapangan.\r\n\r\nSebagai luaran, mahasiswa diwajibkan menyusun laporan ilmiah berbasis studi kasus dari setiap lokasi kunjungan. Selain itu, hasil dokumentasi visual yang dikumpulkan selama kegiatan direncanakan akan dipamerkan di lingkungan kampus sebagai bentuk diseminasi karya dan pengetahuan.\r\n\r\nMelalui kegiatan ini, Program Studi DKV Universitas Trisakti menegaskan komitmennya dalam menciptakan pembelajaran yang kontekstual, adaptif, dan relevan dengan kebutuhan industri kreatif masa kini.', '2026-04-23 21:40:12', '2026-04-24 02:00:38', 'mahasiswa-dkv-universitas-trisakti-gelar-kkl-di-yogyakarta-perkuat-koneksi-industri-kreatif');

