--
-- Table structure for table `fakultas`
--

CREATE TABLE `fakultas` (
  `id` int(11) NOT NULL,
  `nama` varchar(150) NOT NULL,
  `slug` varchar(160) NOT NULL,
  `warna` varchar(10) NOT NULL DEFAULT '#1a3a6b',
  `bg_tipe` enum('youtube','image') NOT NULL DEFAULT 'image',
  `bg_value` varchar(255) DEFAULT NULL,
  `jmlh_mahasiswa` int(11) NOT NULL DEFAULT 0,
  `jmlh_guru_besar` int(11) NOT NULL DEFAULT 0,
  `jmlh_doktor` int(11) NOT NULL DEFAULT 0,
  `jmlh_pengajar` int(11) NOT NULL DEFAULT 0,
  `sejarah_singkat` text DEFAULT NULL,
  `nama_dekan` varchar(150) DEFAULT NULL,
  `foto_dekan` varchar(255) DEFAULT NULL,
  `sambutan_dekan` text DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Dumping data for table `fakultas`
--

INSERT INTO `fakultas` (`id`, `nama`, `slug`, `warna`, `bg_tipe`, `bg_value`, `jmlh_mahasiswa`, `jmlh_guru_besar`, `jmlh_doktor`, `jmlh_pengajar`, `sejarah_singkat`, `nama_dekan`, `foto_dekan`, `sambutan_dekan`, `created_at`, `updated_at`) VALUES
(2, 'OKE Fakultas Hukum', 'oke-fakultas-hukum', '#ff0000', 'youtube', 'https://youtu.be/OGCNIjS8_gg?si=a6puS4xkC40EiVN9', 3696, 5, 72, 96, 'OKE Fakultas Hukum Universitas Trisakti merupakan salah satu fakultas tertua di lingkungan Universitas Trisakti, yang didirikan bersamaan dengan lahirnya Universitas Trisakti pada tanggal 29 November 1965 oleh Dr. Sjarif Thajeb selaku Menteri Perguruan Tinggi dan Ilmu Pengetahuan Republik Indonesia. Pendirian tersebut didasarkan pada Surat Keputusan Menteri PTIP Nomor 013/dar Tahun 1965 juncto Nomor 014/dar Tahun 1965. Pada awal berdirinya, fakultas ini dikenal dengan nama Fakultas Hukum dan Pengetahuan Masyarakat. Seiring dengan penyesuaian kebijakan pendidikan nasional, nama fakultas kemudian berubah menjadi Fakultas Hukum berdasarkan Keputusan Menteri Pendidikan dan Kebudayaan Republik Indonesia Nomor 0333/O/1985 tanggal 27 Juli 1985.\r\n\r\nDalam aspek akademik, Fakultas Hukum Universitas Trisakti telah mengalami berbagai tahapan penting. Pada tahun 1972, fakultas ini memperoleh status akademik “disamakan” berdasarkan Keputusan Menteri Pendidikan dan Kebudayaan RI Nomor 090/U/1972 untuk Jurusan Hukum Perdata, Hukum Pidana, dan Hukum Internasional. Status ini memberikan pengakuan kesetaraan ijazah dengan perguruan tinggi negeri tanpa syarat pengawasan aktif dari kementerian. Status ini kemudian diperbarui melalui sejumlah keputusan, termasuk Keputusan Nomor 296/U/1981, Keputusan Nomor 333/O/1985, dan terakhir Keputusan Nomor 558/Dikti/Kep/1993.\r\n\r\nProgram pendidikan Strata 1 (S1) mulai diselenggarakan sejak tahun akademik 1986/1987 melalui Keputusan Rektor Universitas Trisakti Nomor 069/Usakti/SKR/VIII/1986. Sejak saat itu, fakultas ini telah melaksanakan sistem pendidikan berbasis Sistem Kredit Semester (SKS) murni. Pengakuan penting lainnya datang pada tahun 1998, saat Fakultas Hukum memperoleh akreditasi “A” dari Badan Akreditasi Nasional Perguruan Tinggi (BAN-PT) berdasarkan Sertifikat Akreditasi Nomor 00439/AK.I.I/UT-CIHK/VIII/1998. Dengan akreditasi ini, ijazah yang diterbitkan tidak lagi memerlukan pengesahan dari Kopertis Wilayah III.\r\n\r\nFakultas Hukum Universitas Trisakti secara konsisten berhasil mempertahankan akreditasi “A” dalam berbagai periode reakreditasi. Peringkat tersebut diperoleh kembali pada tahun 2003, 2008, 2013, dan 2018, menunjukkan kualitas dan mutu pendidikan yang berkelanjutan. Khusus pada tahun 2018, akreditasi “A” ditetapkan melalui Keputusan BAN-PT No. 1288/SK/BAN-PT/Akred/S/V/2018 dan berlaku hingga 8 Mei 2023. Selanjutnya, melalui proses reakreditasi pada tahun 2023, Program Studi Sarjana Ilmu Hukum memperoleh status akreditasi “Unggul” dengan Keputusan BAN PT No. 526/SK/BAN-PT/Ak.KP/S/II/2024.', 'Prof.DR. DRA. Siti Nurbaiti, SH., Mhum', '1776887724_4433b301e810f4bf089f.png', 'OKE Assalamu’alaikum Wr. Wb.\r\n\r\nDengan memanjatkan puji dan syukur kehadirat Allah SWT, kami mengucapkan selamat datang di situs Fakultas Hukum Universitas Trisakti sebagai media edukasi yang berbasis teknologi informatika.\r\n\r\nFakultas Hukum merupakan salah satu Fakultas dalam lingkup Universitas Trisakti. Keberadaannya bersamaan dengan didirikannya Universitas oleh Pemerintah Republik Indonesia pada tanggal 29 November 1965, oleh Dr. Syarif Thayeb selaku Menteri Perguruan TInggi dan Ilmu Pengetahuan Nomor : 013/dar.Tahun 1965 juncto Nomor: 014/dar.Tahun 1965. Nama “Trisakti” merupakan pemberian dan buah pikiran dari Dr. Ir. Soekarno, Presiden pertama Republik Indonesia, yang mengandung makna :\r\n\r\nBerdaulat di bidang politik;\r\nBerdikari di bidang ekonomi; dan\r\nBerkepribadian di bidang kebudayaan.\r\nFakultas Hukum Universitas Trisakti sebagai penyelenggara Pendidikan Tinggi Program Studi Sarjana dan Pascasarjana, mempunyai visi: Menjadi Fakultas Hukum yang andal, berstandar internasional dengan tetap memperhatikan nilai-nilai lokal dalam mengembangkan ilmu pengetahuan hukum untuk meningkatkan kualitas hidup dan peradaban.\r\n\r\nUntuk mencapai visi, misi, dan tujuannya, Program Studi Sarjana Ilmu Hukum Fakultas Hukum Universitas Trisakti memiliki:\r\n\r\nKelas Reguler Pagi (S1) dengan 7 (tujuh) Program Kekhususan yang meliputi : hukum bisnis, hukum keluarga, hukum agraria, hukum pidana, hukum internasional publik, hukum acara, hukum pemerintahan dan perundang-undangan.\r\n Kelas Reguler Sore (S1) bagi karyawan dengan konsentrasi hukum bisnis.\r\nProgram Studi Magister Hukum (S2)dengan konsentrasi hukum bisnis, hukum  agraria dan hukum pidana.\r\nProgram Studi Doktor Ilmu Hukum (S3)\r\nDalam rangka mempersiapkan lulusan Fakultas Hukum yang berminat untuk menjadi advokat, Fakultas Hukum  bekerjasama dengan Peradi juga secara rutin menyelenggarakan Pendidikan Khusus Profesi Advokat (PKPA) yang terbuka untuk umum.\r\n\r\nGuna melengkapi penyelenggaraan pendidikan yang berkualitas, Fakultas Hukum telah menerapkan kurikulum yang merujuk pada Kerangka Kualifikasi Nasional Indonesia (KKNI) dan Kurikulum Program Studi Sarjana Ilmu Hukum yang  berbasis Outcome Based Education (OBE) beserta sistem pembelajarannya, yang didukung oleh berbagai sarana, prasarana dan fasilitas pendidikan yang selalu mengikuti perkembangan ilmu pengetahuan, teknologi dan seni.\r\nDi samping itu selalu terus diupayakan peningkatan kualitas tenaga pengajar,  pelaksanaan kerjasama dengan berbagai instansi  baik di dalam maupun di luar negeri.\r\n\r\nUntuk memperoleh informasi selengkapnya, dipersilahkan untuk menelusuri lebih lanjut situs Fakultas Hukum Universitas Trisakti.\r\n\r\nUcapan terima kasih disampaikan atas kepercayaan masyarakat yang telah memilih Fakultas Hukum Universitas Trisakti bagi putra dan putrinya untuk menempuh pendidikan tinggi di bidang hukum.\r\n\r\nSekian dan Terima Kasih.\r\n\r\nWassalamu’alaikum Wr. Wb.', '2026-04-22 19:53:45', '2026-04-24 02:47:22'),
(3, 'Fakultas Kedokteran Gigi', 'fakultas-kedokteran-gigi', '#bf31c9', 'youtube', 'https://youtu.be/47Ydtofd4mE?si=j4K7Wi8PLcs-y79x', 1325, 4, 40, 120, 'Fakultas Kedokteran Gigi Universitas Trisakti (FKG Usakti), adalah salah satu fakultas dari 9 fakultas yang ada di Universitas Trisakti.  FKG Usakti didirikan sejak tahun 29 November 1965. Universitas Trisakti merupakan Universitas swasta yang didirikan oleh pemerintah melalui SK Menteri PTIP No. 014/dar/65. Diawali dengan mewisuda dan mengambil sumpah kepada  6 (enam)  orang dokter gigi pada  tahun 1968, FKG Usakti mulai melangkah maju memasuki periode pembangunan institusi dan pembangunan fisik. Pada tahun 1972 melalui SK. Mendikbud RI No. 091/u/1972  FKG Usakti mendapatkan STATUS DISAMAKAN yang berarti mempunyai status sama dengan Fakultas Kedokteran Gigi Negeri.  Pada tahun 1975 FKG Usakti berhasil membangun Gedung Klinik Pendidikan 3 lantai yang dilengkapi peralatan yang lebih modern sehingga kualitas pendidikannya dapat lebih ditingkatkan lagi.\r\n\r\nPada tahun 1995, terlaksana peresmian gedung baru Kampus B untuk Fakultas Kedokteran Gigi dan Fakultas Kedokteran yang berlantai 7. FKG Usakti memiliki sarana dental unit modern serta ruang kuliah full AC dan perlengkapan audio visual. Selain terjadi peningkatan sarana dan prasarana, maka pada tahun yang sama diberlakukan kurikulum baru dengan Program Pendidikan 2 Jenjang berdasarkan surat keputusan MENDIKBUD R.I. No. 0310/u/1994. Program pendidikan tersebut adalah: Program Pendidikan Akademik (S1 dengan jumlah kredit sebanyak 145 sks) dengan gelar Sarjana Kedokteran Gigi (SKG) dan  Program Pendidikan Profesi dengan sebutan Dokter Gigi.\r\n\r\nPada tahun 1998, dari Badan Akreditasi Nasional Perguruan Tinggi (BAN-PT), FKG Usakti memperoleh  peringkat A plus dan melalui surat keputusan Nomor 001/BAN-PT/Ak-I/VIII/1998, FKG Usakti ditetapkan sebagai Pembina Program Studi Pendidikan Dokter Gigi FKG  lain di Indonesia.  Melalui status  akreditasi A tersebut, FKG Usakti dipercaya untuk membina FKG Universitas Mahasaraswati di Bali dari tahun 1998 sampai dengan 2001, sehingga Program Studi Pendidikan Dokter Gigi Strata Satu  (S1) Universitas Mahasaraswati tersebut pada tahun 2002 terakreditasi oleh BAN PT dengan peringkat B. Sebagai upaya pengembangan akademik, FKG Usakti mendirikan Program Magister Ilmu Kedokteran Gigi pada tanggal 14 Oktober 1998 melalui Surat Keputusan Direktorat Pendidikan Tinggi No. 370/Dikti/Kep/1998. Untuk selanjutnya program ini disebut dengan Program Studi Magister Ilmu Kedokteran Gigi (PS MIKG FKG Usakti). Pada awal pendiriannnya, pengelolaan PS MIKG FKG Usakti berada di bawah Program Pasca Sarjana Universitas Trisakti, namun sejak 1 September 2003 dikelola oleh FKG Usakti melalui SK Rektor No. 10/USAKTI/SKR/VI/2003.\r\n\r\nFKG Usakti dengan melalui pendekatan Continuous Improvement yaitu secara berkesinambungan memperbaiki diri, telah berhasil mempertahankan status akreditasi A dari BAN-PT sejak tahun 2004, bahkan pada tahun 2003 FKG Usakti memperoleh status terakreditasi dari pemerintah Malaysia. Disamping itu pada tahun 2006 sampai dengan 2009 FKG Usakti  diminta untuk membina suatu College Kedokteran Gigi di Kuala Lumpur yaitu Malaysian Alliance Health Science Academy (MAHSA), sehingga pada tahun 2009 terakreditasi oleh pemerintah Malaysia dan dapat mandiri. Pada tahun 2007 FKG Usakti membina Fakultas Kedokteran Gigi Universitas Sultan Agung, Semarang. Sebagai upaya pengembangan di bidang profesi, FKG Usakti mendirikan Program Studi Pendidikan Dokter Gigi Spesialis Konservasi Gigi (PS PDGS KG FKG Usakti)  pada tahun 2009. Tahun 2010 FKG Usakti terakreditasi kembali berdasarkan Surat Keputusan BAN PT Nomor: 020/BAN-PT/Ak-XIII/S1/X/2010 tentang Hasil Peringkat Akreditasi Fakultas Kedokteran Gigi Universitas Trisakti dengan status “Terakreditasi dengan Peringkat A”.\r\n\r\nPada tahun 2015, LAM-PTKes yang dibentuk oleh BAN PT memberikan akreditasi A kepada Program Studi Pendidikan Dokter Gigi FKG Usakti berdasarkan keputusan LAM-PTKes No: 0004/LAM-PTKes/Akr/Sar/IX/2015 tertanggal 21 September 2015, serta akreditasi A untuk Program Studi Profesi Dokter Gigi FKG Usakti melalui SK LAM-PTKes No: 0005/LAM-PTKes/Akr/Pro/IX/2015 tertanggal 21 September 2015.Pada tahun 2016, PS PDGS KG FKG Usakti memperoleh akreditasi A dari LAM-PTKES untuk Program Studi Spesialis Konservasi Gigi melalui surat keputusan No 0555/LAM-PTKes/Akr/Spe/V/2016; akreditasi ini sampai dengan tahun 2021. Pada tahun 2017, PS MIKG memperoleh akreditasi B melalui surat keputusan No 0148/LAM-PTKes/Akr/Mag/IV/2017; akreditasi ini sampai dengan tahun 2022. Pada tahun 2020, LAM-PTKes memberikan akreditasi A kepada Program Studi Pendidikan Dokter Gigi FKG Usakti berdasarkan keputusan LAM-PTKes No:0678/LAM-PTKES/Akr/Sar/XII/2020, serta akreditasi A untuk Program Studi Profesi Dokter Gigi FKG Usakti melalui SK LAM-PTKes No: 0679/LAM-PTKES/Akr/Sar/XII/2020.\r\n\r\nIndikator keberhasilan yang lain terlihat dari meningkatnya jumlah peminat mahasiswa baru, pengembangan kualitas dosen, prestasi karya ilmiah dosen diantaranya menghasilkan rancangan dan karya teknologi yang dipatenkan oleh Dirjen Hak Kekayaan Intelektual Kementrian Hukum dan Hak Azazi Manusia, serta riset mahasiswa yang mampu bersaing dengan mahasiswa FKG lainnya baik tingkat nasional maupun lingkup ASEAN. Sebagai salah satu kekuatan yang lain adalah dimilikinya Unit Afiliasi yang merupakan upaya mendaya gunakan potensi akademik untuk dapat menghasilkan dana di luar dana yang diperoleh dari mahasiswa.\r\n\r\nDi dalam pelaksanaan Tri Dharma Perguruan Tinggi, FKG Usakti bekerja sama dengan Rumah Sakit Gigi dan Mulut (RSGM FKG Usakti). RSGM FKG Usakti telah terakreditasi PARIPURNA edisi SNARS 2018 dari Komite Akreditasi Rumah Sakit (KARS) serta telah dikukuhkan sebagai RSGM-Pendidikan pada 5 Juni 2020 oleh Kementerian Kesehatan RI. Pada tahun 2020 Universitas Trisakti telah meningkatkan fasilitas RSGM-P FKG Usakti dengan membuat 27 ruang klinik bertekanan negatif, guna menghadapi pandemi global Covid-19. RSGMP FKG Usakti  memiliki fungsi ganda yaitu disamping sebagai fasilitas belajar klinik berbasis rumah sakit, yang diharapkan dapat meningkatkan kualitas kompetensi lulusan dokter gigi, juga sebagai fasilitas pelayanan kesehatan gigi kepada masyarakat umum yang dapat menghasilkan dana pendukung bagi  FKG Usakti.\r\n\r\nFKG Usakti merupakan bagian yang tidak terpisahkan dari sistem pendidikan nasional yang secara nyata  ikut mencerdaskan dan mendidik anak bangsa, khususnya dalam bidang ilmu kedokteran gigi. Sampai saat ini FKG Usakti telah memiliki lebih dari 6000 alumni yang tersebar di seluruh pelosok tanah air bahkan menyebar ke mancanegara Amerika Serikat, Australia, Belanda dan lain-lain. Untuk menjadi Fakultas Kedokteran Gigi yang andal dan terkemuka, bertaraf internasional masih diperlukan semangat, kerja keras serta doa dari seluruh civitas academica dan para alumni dimanapun berada.', 'drg. Wiwiek Poedjiastoeti, M.Kes, Sp.BMM, Ph.D', '1776905181_731b33367ca8dd54c1ef.png', 'Berdiri sejak 1965, Fakultas Kedokteran Gigi Universitas Trisakti (FKG Usakti) telah dikenal sebagai penghasil dokter gigi-dokter gigi handal. Seiring dengan kemajuan Ilmu Pengetahuan dan Teknologi, FKG Usakti terus mengembangkan diri serta menjawab segala tantangan pada bidang kedokteran gigi.\r\n\r\nHal ini sesuai dengan Visi FKG Usakti, yaitu menjadi Fakultas Kedokteran Gigi yang terkemuka di Indonesia, bermutu internasional, dalam mengembangkan ilmu pengetahuan, teknologi dan seni di bidang kedokteran gigi, untuk meningkatkan kualitas hidup dan peradaban manusia di wilayah Asia Pasifik.\r\nPendidikan di FKG Usakti lebih menekankan melalui pendekatan yang bersifat persuasif kepada para peserta didik dengan membudayakan Penelitian serta Pengabdian kepada Masyarakat, sehingga menghasilkan lulusan dengan kemampuan analisis tinggi, berpikir kritis serta mampu menjawab tantangan dunia kedepan yang tetap memiliki jiwa bebas namun terarah serta percaya diri tinggi, sebagai calon pemimpin masa depan di bidangnya masing-masing.\r\n\r\nFKG Usakti juga menjawab tuntutan masyarakat pada kebutuhan tenaga kesehatan gigi yang berkualitas dengan mengimplementasikan Standar Kompetensi Dokter Gigi Indonesia kedalam Kurikulum FKG Usakti yang komprehensif dan bermutu tinggi dengan output yang terukur. Hal tersebut dapat dilaksanakan karena FKG Usakti memiliki Sumber Daya Manusia yang berkualitas serta diakui dalam maupun luar negeri dengan didukung oleh komponen penunjang seperti Sistem Informasi Manajemen Fakultas dan sarana prasarana pendidikan, baik akademik maupun profesi.\r\n\r\nMelalui kolaborasi dengan para stakeholder FKG Usakti, kami terus mengembangkan sistem pendidikan yang terukur dan dievaluasi secara periodik. Hal ini diwujudkan melalui berbagai hal antara lain: (1) Kerjasama dengan alumni yang telah tersebar ke berbagai penjuru Indonesia hingga mancanegara di berbagai kegiatan, (2) Kemitraan dengan pihak terkait baik pemerintah maupun swasta, yang menjadi mitra kerja FKG Usakti dalam berbagai kegiatan seperti pertemuan Ilmiah dan Non Ilmiah, (3) Kerjasama bersama masyarakat yang menjadi mitra dalam edukasi kesehatan gigi dan mulut secara khusus dan kesehatan secara umum.', '2026-04-23 00:46:21', '2026-04-23 00:46:21'),
(4, 'Fakultas Seni Rupa dan Desain', 'fakultas-seni-rupa-dan-desain', '#06feab', 'youtube', 'https://youtu.be/DzNe3tNaiL8?si=0uVLFEBfgsEm7PhV', 6541, 1, 8, 39, 'Pendirian Fakultas Seni Rupa dan Desain berawal dari didirikannya Departemen Seni Rupa sebagai bagian dari Fakultas Teknik Universitas Trisakti pada tahun 1969 bersama dengan Departemen Teknik Sipil, Teknik Elektro dan Teknik Arsitektur. Pada tahun 1974 Departemen Seni Rupa di lingkungan Fakultas Teknik diubah menjadi Jurusan Seni Rupa yang mempunyai Sub Jurusan Arsitektur Interior, Industrial Design dan Seni Lukis. Pada tahun 1978 secara resmi Sub. Jurusan Seni Lukis ditutup. Bersamaan dengan itu dibentuk Sub. Jurusan Desain Grafis yang pada saat itu mulai diminati masyarakat dan melihat kepada permintaan pasar.\r\n\r\nPeminat terhadap Fakultas Teknik semakin tinggi dan jumlah mahasiswanya bertambah banyak sehingga perlu dilakukan pengelompokan disiplin ilmu. Berdasarkan kondisi itu maka Jurusan Teknik Arsitektur, Sipil dan Seni Rupa digabungkan menjadi satu Fakultas, yaitu Fakultas Teknik Sipil dan Perencanaan, dengan Jurusan Teknik Arsitektur, Jurusan Teknik Sipil dan Jurusan Seni Rupa dan Desain. Ditahun yang sama Sub. Jurusan berubah menjadi Program Pengutamaan Studi (PPS), yaitu PPS Desain Interior, PPS Desain Produk Industri dan PPS Desain Grafis.\r\n\r\nTahun 1996 Jurusan Desain berkembang menjadi Fakultas Seni Rupa dan Desain berdasarkan Surat Keputusan Direktur Jenderal Pendidikan dan Kebudayaan Republik Indonesia Nomor : 431/Dikti/Kep/1995. FSRD mempunyai 2 jurusan, yaitu Jurusan Desain dan Jurusan Seni Rupa. Jurusan Desain mempunyai 3 program studi, yaitu Program Studi Desain Interior, Program Studi Desain Produk dan Program Studi Desain Komunikasi Visual, adapun Jurusan Seni Rupa mempunyai Program Studi Fotografi yang pernah memiliki PPS Video-Film.\r\n\r\nPada Tahun 2007 Fakultas memiliki Program Diploma Tiga (D3) Desain Komunikasi Visual dan masih bertahan hingga saat ini walaupun dengan jumlah mahasiswa yang masih sangat terbatas.\r\nPada tahun 2009 Fakultas memiliki Program Pasca Sarjana (S2) Desain dan merupakan Program Pasca Sarjana yang berorientasi Desain pertama di Universitas Swasta di Jakarta.\r\n\r\nPada pertengahan tahun 2013, struktur organisasi yang terdiri dari Fakultas, Jurusan dan Program Studi memutuskan untuk membubarkan Jurusan, karena efisiensi dan dalam meningkatkan kinerja program studi. Sedangkan Program Studi Desain Produk membuka 3 (tiga) Program Pengutamaan Studi (PPS) yang terdiri dari PPS. Desain Produk Umum, PPS. Desain Transportasi dan PPS. Desain Kriya.', 'Prof. Dr. Wegig Murwonugroho, M.Hum', '1776905395_f05ac49e6cc7922561cd.jpg', 'Pada saat ini Fakultas Seni Rupa dan Desain (FSRD) telah menetapkan Visi “Menjadi Fakultas Seni Rupa dan Desain yang andal di Indonesia, mempunyai standar internasional dalam keilmuannya, dengan tetap memperhatikan tradisi dan kearifan lokal dalam mengembangkan seni, desain, ilmu pengetahuan dan teknologi, guna meningkatkan kualitas hidup dan peradaban”. Visi tersebut menjadi motivasi kami untuk bekerja keras meraih target posisi sebagai lembaga pendidikan tinggi desain yang berorientasi pada Eksplorasi Budaya Masyarakat Indonesia yang dikemas dalam komunitas urban dengan wawasan global, pemanfaatan teknologi dan seni.\r\n\r\nUniversitas Trisakti memiliki Fakultas Seni Rupa dan Desain yang berdiri sejak tahun 1985 dengan 4 (empat) Program Studi yang lengkap, masing-masing Program Studi Desain Interior, Desain Produk, Desain Komunikasi Visual dan Fotografi. Dalam perjalanan panjangnya saat ini berdasarkan putusan BAN-PT pada tahun 2016 Program Studi Desain Produk, Desain Komunikasi Visual, Fotografi, memperoleh nilai akreditasi “A”, dan Program Studi Desain Interior memperoleh nilai akreditasi “B”.\r\n\r\nPada tahun 2006 resmi dioperasikan Program Magister Desain Produk yang pertama untuk Perguruan Tinggi Swasta dengan nilai akreditasi “A”.\r\n\r\nProgram Studi Desain Interior, Desain Komunikasi Visual, Desain Produk dan Fotografi merupakan Program Studi yang mencetak sarjana-sarjana di bidang desain yang profesional dan bukan hanya bisa menciptakan karya desain, namun juga harus dapat mengkomunikasikan ide/pendapat/pikiran melalui bahasa visual lewat karyanya.\r\n\r\nMahasiswa Desain di bawah Fakultas Seni Rupa dan Desain Universitas Trisakti mempelajari teori dan berlatih keterampilan seni dan desain agar memiliki dasar yang kuat dalam berkarya. Mahasiswa juga dilatih untuk memacu kreatifitas, memiliki kepekaan estetika dan mampu mengapresiasi karya desain.\r\n\r\nIde cemerlang bisa hilang, bila tak terealisasikan menjadi karya. Karya yang indah tak akan terwujud tanpa dukungan sumberdaya. Namun bila keterampilan manajemen dimiliki, maka keterampilan ini bisa meningkatkan kualitas sarana/prasarana bagi perkembangan kreatifitas dan kemunculan karya-karya selanjutnya. Mahasiswa Desain FSRD Universitas Trisakti dilatih dalam hal ini, sehingga mereka punya kemampuan untuk menjalankan bisnis desain dan berwirausaha.\r\n\r\n \r\n\r\nDekan,\r\n\r\nProf. Dr. Wegig Murwonugroho, M.Hum', '2026-04-23 00:49:55', '2026-04-23 00:49:55'),
(5, 'Fakultas Arsitektur Lanskap dan Teknologi Lingkungan', 'fakultas-arsitektur-lanskap-dan-teknologi-lingkungan', '#0052cc', 'youtube', 'https://youtu.be/QEXhTN1ZLE8?si=99V4A9i-Zgzl-jiI', 438, 2, 17, 37, 'Berdirinya Fakultas Arsitektur Lanskap dan Teknologi Lingkungan (FALTL) berawal dari pendirian Akademi Arsitektur Pertamanan (AKAP), atas prakarsa Gubernur KDH-DCI Jakarta Raya, yang kemudian pada tahun 1970 diserahkan kepada Yayasan Trisakti untuk dikelola dan dibina.\r\n\r\nTahun 1974 AKAP Trisakti ditingkatkan menjadi Sekolah Tinggi Arsitektur Pertamanan Trisakti (STAPI), dengan lama pendidikan yang semula 3,5 tahun menjadi 5 tahun. Tahun 1977, sesuai dengan kebijakan Yayasan dan Universitas, didirikan Fakultas Arsitektur Lansekap (FAL), dengan satu jurusan/program studi yaitu Jurusan Arsitektur Lansekap, sebagai pengganti STAPI. Tahun 1985, Fakultas Arsitektur Lansekap (FAL) berkembang menjadi Fakultas Arsitektur Lanskap dan Teknologi Lingkungan (FALTL) dengan penambahan jurusan/program studi S1 baru yaitu Jurusan Teknik Lingkungan. Kemudian pada tahun 1996 dibuka jurusan Teknik Planologi dengan Program Studi Perencanaan Wilayah dan Kota. Ketiga Program Studi tersebut telah terakreditasi Nasional dan Internasional. Program Studi Teknik Lingkungan telah terakreditasi internasional dari Indonesian Accreditation Board for Engineering Education (IABEE) dan Tersertifikasi dari Asean University Network-Quality Assurance (AUN-QA).', 'Dr. Ir. Silia Yuslim, M.T', '1776905725_ddad366199eda547349a.jpg', 'Fakultas Arsitektur Lanskap dan Teknologi Lingkungan (FALTL) Universitas Trisakti berkomitmen menjadi garda terdepan dalam menghasilkan solusi berbasis ilmu pengetahuan, teknologi, dan seni (IPTEKS) dalam menghadapi tantangan global seperti perubahan iklim, krisis lingkungan, dan kebutuhan pembangunan berkelanjutan.\r\n\r\nSebagai fakultas yang menaungi tiga program studi: Arsitektur Lanskap, Teknik Lingkungan, dan Perencanaan Wilayah dan Kota, FALTL berperan penting dalam mendidik generasi yang tidak hanya kompeten di bidangnya tetapi juga memiliki sensitivitas terhadap isu-isu lokal, nasional, dan global.\r\n\r\n \r\n\r\nArsitektur Lanskap, program studi yang berdiri tahun1970 ini melahirkan sarjana yang kompeten dalam mengembangkan perencanaan/desain dan pengelolaan ruang terbuka hijau, kawasan alami, budaya, pariwisata, dan aset lingkungan untuk keberlanjutan sosial, ekonomi, dan ekologis.\r\n\r\nTeknik Lingkungan, program studi yang berdiri tahun 1986 ini menghasilkan sarjana teknik yang kompeten dalam mengelola kualitas lingkungan melalui perencanaan sistem air, limbah, dan solusi inovatif untuk menjaga kesehatan lingkungan serta mitigasi dampak pembangunan terkait pencemaran tanah, air, dan udara.\r\n\r\nPerencanaan Wilayah dan Kota, program studi yang berdiri tahun 1996 ini melahirkan sarjana yang kompeten dalam mengintegrasikan perencanaan kebijakan, tata ruang, dan pengembangan wilayah berbasis potensi lokal untuk mendukung pembangunan wilayah dan kota yang inklusif, efisien dan kesejahteraan masyarakat yang berkelanjutan.\r\n\r\nKami terus berinovasi dalam kurikulum agar relevan dengan perkembangan IPTEKS global, memastikan lulusan kami siap menjawab kebutuhan masyarakat sekaligus berkontribusi terhadap keberlanjutan planet kita.\r\n\r\nMelalui FALTL, Universitas Trisakti juga berperan aktif dalam mewujudkan visi untuk meningkatkan kualitas hidup dan peradaban. Dengan semangat ini, kami mengundang generasi muda yang peduli terhadap keberlanjutan lingkungan dan pembangunan untuk bergabung bersama kami membangun masa depan yang lebih baik.\r\n\r\nSemoga Tuhan Yang Maha Esa senantiasa membimbing langkah kita dalam berkarya demi kebaikan bersama.', '2026-04-23 00:55:25', '2026-04-23 00:55:25');

