CREATE TABLE `prodi` (
  `id` int(11) NOT NULL,
  `id_fakultas` int(11) NOT NULL,
  `nama` varchar(150) NOT NULL,
  `slug` varchar(160) NOT NULL,
  `jenjang` enum('D3','S1','S2','S3','Profesi','Spesialis') NOT NULL DEFAULT 'S1',
  `bg_tipe` enum('youtube','image') NOT NULL DEFAULT 'image',
  `bg_value` varchar(255) DEFAULT NULL,
  `tentang` text DEFAULT NULL,
  `sejarah` text DEFAULT NULL,
  `nama_kaprodi` varchar(150) DEFAULT NULL,
  `foto_kaprodi` varchar(255) DEFAULT NULL,
  `sambutan_kaprodi` text DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

