INSERT INTO `prodi` (`id`, `id_fakultas`, `nama`, `slug`, `jenjang`, `bg_tipe`, `bg_value`, `tentang`, `sejarah`, `nama_kaprodi`, `foto_kaprodi`, `sambutan_kaprodi`, `created_at`, `updated_at`) VALUES
(1, 2, 'Sarjana Ilmu Hukum', 'sarjana-ilmu-hukum', 'S1', 'youtube', 'https://youtu.be/OGCNIjS8_gg?si=a6puS4xkC40EiVN9', 'Fakultas Hukum sebagai program studi yang menyelenggarakan pendidikan strata 1, didirikan tanggal 29 November 1965 berdasarkan Surat Keputusan Menteri Perguruan Tinggi dan Ilmu Pengetahuan Nomor: 013/dar Tahun 1965 tentang Penggantian Nama Res Publica menjadi Universitas Trisakti dan Pembentukan Presidium Sementara Untuk Universitas tersebut, dan Keputusan Menteri Perguruan Tinggi dan Ilmu Pengetahuan Nomor: 014/dar Tahun 1965 tentang Pembukaan Kembali Universitas Res Publica di Jakarta Kini Bernaung di Bawah Nama Universitas Trisakti. Berdasarkan Keputusan Rektor Universitas Trisakti Nomor:069/Usakti/SKR/VIII/1986 Fakultas Hukum telah melaksanakan pendidikan strata 1 berdasarkan Sistem Kredit Semester (SKS). Adapun perkembangan UPPS diawali dengan Sertifikat Akreditasi Nomor: 00439/AK.I.I/UT-CIHK/VIII/1998 yang diterbitkan oleh Departemen Pendidikan dan Kebudayaan Republik Indonesia dengan akreditas peringkat A (Baik Sekali). Kemudian pada tahun 2003 (Keputusan Badan Akreditasi Nasional Perguruan Tinggi Departemen Pendidikan Nasional RI Nomor: 036/BAN-PT/S1/X/2003) dan tahun 2008 (Keputusan Badan Akreditasi Nasional Perguruan Tinggi Nomor: 027/BAN-PT/Ak-XI/S1/X/2008), serta tahun 2013 (Keputusan Badan Akreditasi Nasiional Perguruan Tinggi Departemen Nasional Nomor 227/SK/BAN-PT/AK-XVI/S/XI/2013 tertanggal 09 November 2013)  telah memperoleh akreditasi dengan kualifikasi A. Tahun 2018, melalui Keputusan Badan Akreditasi Nasional Perguruan Tinggi Departemen Pendidikan Nasional No.1288/SK/BAN-PT/Akred/S/V/2018 Program Studi Ilmu Hukum Fakultas Hukum Usakti terakreditasi dengan peringkat A.\r\nTata kerja organisasi Fakultas Hukum Universitas Trisakti dipimpin oleh Dekan, yang dibantu oleh Wakil Dekan I, II,III dan IV. Para Wakil Dekan dibantu oleh Asisten Wakil Dekan, yaitu Asisten Wakil Dekan I, III dan IV. Fakultas Hukum Universtas Trisakti terdiri dari Program Studi Sarjana Hukum, Program Studi Magister Hukum yang dimulai pada tahun 2002 dan Program Studi Doktor Ilmu Hukum sejak tahun 2008, yang masing-masing diketuai Ketua Program Studi.\r\nStruktur organisasi fakultas selanjutnya adalah Bagian. Fakultas Hukum Universitas Trisakti terdiri dari 8 (delapan) bagian, yang masing-masing diketuai  Ketua Bagian yang dibantu oleh Sekretaris Bagian. Bagian adalah suatu wadah kelompok dosen dalam satu cabang ilmu yang merupakan unsur pelaksana akademik dan juga melaksanakan pengelolaan sumber daya akademik bagi pengembangan cabang ilmu yang bersangkutan dan sarananya. Bagi mahasiswa, terdapat 7 (tujuh) Program Kekhususan yang merupakan wadah yang mengelompokkan mahasiswa sesuai dengan minat, bakat dan kemampuan akademiknya, yang meliputi:\r\n\r\nPK I    : Hukum Bisnis\r\nPK II   : Hubungan Antara Sesama Anggota Masyarakat\r\nPK III  : Hukum Agraria\r\nPK IV  : Pencegahan dan Penanggulangan kejahatan\r\nPK V    : Hukum Transnasional\r\nPK VI  : Praktisi Hukum\r\nPK VII : Hukum Pemerintahan dan Perundang-undangan\r\n\r\nPusat Studi yang merupakan unsur pelaksana akademik yang bertugas menyelenggarakan kegiatan penelitian secara mendalam dan pengembangan serta pengabdian kepada masyarakat dalam bidang Ilmu Hukum. Fakultas Hukum memiliki 7 (tujuh) Pusat Studi yang dipimpin oleh seorang Ketua Pusat Studi', 'Fakultas Hukum sebagai program studi yang menyelenggarakan pendidikan strata 1, didirikan tanggal 29 November 1965 berdasarkan Surat Keputusan Menteri Perguruan Tinggi dan Ilmu Pengetahuan Nomor: 013/dar Tahun 1965 tentang Penggantian Nama Res Publica menjadi Universitas Trisakti dan Pembentukan Presidium Sementara Untuk Universitas tersebut, dan Keputusan Menteri Perguruan Tinggi dan Ilmu Pengetahuan Nomor: 014/dar Tahun 1965 tentang Pembukaan Kembali Universitas Res Publica di Jakarta Kini Bernaung di Bawah Nama Universitas Trisakti. Berdasarkan Keputusan Rektor Universitas Trisakti Nomor:069/Usakti/SKR/VIII/1986 Fakultas Hukum telah melaksanakan pendidikan strata 1 berdasarkan Sistem Kredit Semester (SKS).\r\n\r\nAdapun perkembangan UPPS diawali dengan Sertifikat Akreditasi Nomor: 00439/AK.I.I/UT-CIHK/VIII/1998 yang diterbitkan oleh Departemen Pendidikan dan Kebudayaan Republik Indonesia dengan akreditas peringkat A (Baik Sekali). Kemudian pada tahun 2003 (Keputusan Badan Akreditasi Nasional Perguruan Tinggi Departemen Pendidikan Nasional RI Nomor: 036/BAN-PT/S1/X/2003) dan tahun 2008 (Keputusan Badan Akreditasi Nasional Perguruan Tinggi Nomor: 027/BAN-PT/Ak-XI/S1/X/2008), serta tahun 2013 (Keputusan Badan Akreditasi Nasional Perguruan Tinggi Departemen Nasional Nomor 227/SK/BAN-PT/AK-XVI/S/XI/2013 tertanggal 09 November 2013)  telah memperoleh akreditasi dengan kualifikasi A. Tahun 2018, melalui Keputusan Badan Akreditasi Nasional Perguruan Tinggi Departemen Pendidikan Nasional No.1288/SK/BAN-PT/Akred/S/V/2018 Program Studi Ilmu Hukum Fakultas Hukum Usakti terakreditasi Unggul. Melalui Surat Keputusan Direktur Dewan Eksekutif Badan Akreditas Nasional Perguruan Tinggi nomor 526/SK/BAN-PT/Ak.KP/S/II/2024 tanggal 27 Februari 2024 tentang Konversi Peringkat Akreditasi Program Studi Ilmu Hukum pada Program Sarjana Universitas Trisakti, mengonversi Peringkat Akreditasi Prodi SIH pada Program Sarjana Universitas Trisakti sebagaimana tercantum dalam Surat Keputusan Badan Akreditasi Nasional Perguruan Tinggi Nomor 1538/SK/BAN- PT/Ak.Ppj/S/IV/2023 tentang Peringkat Akreditasi Prodi SIH pada Program Sarjana Universitas Trisakti menjadi UNGGUL dengan Nilai 376.\r\n\r\nProgram Studi Sarjana Ilmu Hukum Fakultas Hukum Universitas Trisakti diketuai oleh Maya Indrasti Notoprayitno, SH.,MSi.,PhD dengan sekretaris Yulia Fitriliani, SH.,MH.\r\n\r\nTerdapat 8 (delapan) bagian yang masing-masing diketuai oleh  Ketua Bagian yang dibantu oleh Sekretaris Bagian. Bagian adalah suatu wadah kelompok dosen dalam satu cabang ilmu yang merupakan unsur pelaksana akademik dan juga melaksanakan pengelolaan sumber daya akademik bagi pengembangan cabang ilmu yang bersangkutan. Bagi mahasiswa, terdapat 7 (tujuh) Peminatan yang merupakan wadah yang mengelompokkan mahasiswa sesuai dengan minat, bakat dan kemampuan akademiknya, yang meliputi:\r\n\r\nPeminatan I    : Hukum Bisnis\r\nPeminatan II   : Hukum Keluarga\r\nPeminatan III  : Hukum Pertanahan\r\nPeminatan IV  : Hukum Pidana\r\nPeminatan V    : Hukum Internasional \r\nPeminatan VI  : Hukum Acara\r\nPeminatan VII : Hukum Kenegaraan\r\n\r\nPeminatan VIII : Hukum dan Kebijakan\r\n\r\nPada tahun 2015 Fakultas Hukum Universitas Trisakti telah membuka Kelas Reguler Sore Program Studi Sarjana Ilmu Hukum yang di khususkan bagi karyawan yang berminat melanjutkan studi.\r\n\r\nKoordinator Kelas Sore adalah Dr. Dhany Rahmawan, SH.,MH dan sekretaris Dr. Novina Sri Indiraharti, SH.,MH\r\n\r\nUntuk Kelas Reguler Sore Khusus menyelenggarakan perkuliahan dengan peminatan hukum bisnis.', 'Maya Indrastasi Notoprayitno, S.H., M.Si, Ph.D.', '1776923355_de5c296ddcf21db5d095.png', 'Salam,\r\n\r\nSelamat datang di laman resmi Program Studi Sarjana Ilmu Hukum Fakultas Hukum Universitas Trisakti, kampus yang dikenal luas sebagai Kampus Reformasi, tempat lahirnya insan-insan yang berpikir kritis, berintegritas tinggi, dan memiliki komitmen kuat terhadap keadilan dan perubahan sosial.\r\n\r\nProgram Studi Sarjana Ilmu Hukum Universitas Trisakti hadir dengan semangat untuk mencetak sarjana hukum yang unggul, berdaya saing global, dan berdampak bagi masyarakat. Melalui pembelajaran berbasis perbandingan hukum (comparative law) dan penguatan tridarma perguruan tinggi, kami berupaya menyiapkan lulusan yang tidak hanya memahami hukum sebagai norma, tetapi juga sebagai instrumen pembaharuan dan keadilan sosial.\r\n\r\nSebagai bagian dari Kampus Berdampak, kami berkomitmen untuk mengembangkan inovasi hukum yang menjawab tantangan zaman: transformasi digital, keberlanjutan, dan keadilan inklusif. Dosen-dosen kami aktif dalam riset nasional maupun internasional, kolaborasi lintas sektor, serta kegiatan yang memperkuat peran hukum dalam mewujudkan masyarakat yang beradab dan berkeadilan.\r\n\r\nKami mengundang para calon mahasiswa yang memiliki semangat untuk belajar, berkontribusi, dan membawa perubahan positif untuk bergabung bersama kami. Jadilah bagian dari keluarga besar Fakultas Hukum Universitas Trisakti — tempat belajar hukum, membangun karakter, dan menebar kebermanfaatan bagi bangsa dan dunia.\r\n\r\nTerima kasih telah mengunjungi laman kami.\r\nSelamat bergabung dan mari bersama membangun masa depan hukum Indonesia yang lebih baik.', '2026-04-23 01:06:51', '2026-04-23 05:50:06'),
(3, 2, 'Doktor Ilmu hukum', 'doktor-ilmu-hukum', 'S3', 'youtube', 'https://youtu.be/7_3Tr0Vj8-4?si=g9Vc9vX7maBr7f2P', 'Program Doktor Ilmu Hukum Universitas Trisakti merupakan salah satu Program Studi lanjutan untuk mengambil gelar Doktor (Dr.) dalam bidang ilmu hukum dalam lingkup Fakultas Hukum Universitas Trisakti. Program Studi ini didirikan dalam upaya untuk menampung minat para lulusan magister (s2) baik dalam bidang hukum maupun dalam bidang keilmuan lainnya yang ingin mengembangkan keilmuan dalam bidang hukum yang terangkum dalam tujuan Program Studi Doktor Ilmu Hukum diantaranya :\r\n\r\n1. Menghasilkan Doktor Ilmu Hukum yang sesuai dengan standar nasional pendidikan.\r\n2. Menghasilkan Doktor Ilmu Hukum yang selalu mengembangkan kemampuan akademik dan kemampuan profesionalnya melalui kegiatan penelitian interdisipliner;\r\n3. Menghasilkan Doktor Ilmu Hukum yang memiliki kompetensi akademik sesuai dengan persyaratan ilmiah;\r\n4. Menghasilkan Doktor Ilmu Hukum yang memiliki kompetensi akademik sesuai dengan kebutuhan masyarakat;\r\n5. Menghasilkan Doktor Ilmu Hukum yang memiliki kepribadian sesuai dengan Trikrama Trisakti dan nilai-nilai lokal.\r\n6. Menghasilkan Doktor Ilmu Hukum yang memiliki wawasan kebangsaan;\r\n7. Menghasilkan Doktor Ilmu Hukum yang dapat menerapkan ilmu pengetahuan hukum yang dimilikinya untuk \r\nmengembangkan ilmu pengetahuan hukum dan meningkatkan kualitas hidup dan peradaban;\r\n8. Menghasilkan Doktor Ilmu Hukum yang memiliki wawasan internasional;\r\n9. Meningkatkan kualitas pendidikan di program studi Doktor Ilmu Hukum;\r\n10. Mewujudkan budaya akademik yang memacu pengembangan diri melalui proses pembelajaran yang produktif, efektif dan efisien dalam membangun masyarakat adab (civil society);\r\n11. Memupuk budaya loyal dan bersikap kritis terhadap almamater bagi warga kampus dan alumni;\r\n12. Meningkatkan komitmen manajemen dan menegakkan good faculty governance serta menyejahterakan warga Fakultas Hukum untuk mempertahankan kejayaan Universitas Trisakti.', 'Program Studi Doktor Ilmu Hukum Universitas Trisakti didirikan pertama kali pada tahun 2008 dengan Surat Keputusan Direktur Jendral Pendidikan Tinggi Departeman Pendidikan Nasional Nomor: 910/D/T/2008. Ijin penyelenggaraan ini kemudian diperpanjang dengan Surat Keputusan Direktur Jendral Pendidikan Tinggi Nomor 5059/D/T/K111/2010. Selain itu Program Studi Doktor Ilmu Hukum Universitas Trisakti telah terakreditasi BAN PT dengan peringkat B (Baik).', 'Dr. Dyah Setyorini, S.H., SpN., M.H', '1776924155_3ab65a13deb1c2b7479c.png', 'Puji syukur di panjatkan kepada Tuhan Yang Maha Esa atas karunia yang diberikan sepada kita semua.\r\n\r\nProgram Studi Doktor Ilmu Hukum Universitas Trisakti berorientasi pada kebutuhan pasar, bukan hanya untuk memenuhi kebutuhan industri nasional saja tapi juta untuk memenuhi kebutuhan dunia internasional. Hal ini di dukung dengan kurikulum yang selalu sejalan dan relevan dengan kebutuhan dunia industri dan pasar yang terus berkembang, sarana dan prasarana yang memadai, sumber daya alam yang unggul serta suasana akademik yang baik. Sehingga lulusan Program Studi Doktor Ilmu Hukum Universitas Trisakti diharapkan mampu mengembangkan ilmu hukum, berwawasan internasional dengan tetap memperhatikan kearifan lokal, kooperatif, inovatif, mandiri, berjiwa kewirausahaan, menguasai teknologi serta dapat menyelesaikan permasalahan-permasalahan hukum.', '2026-04-23 06:02:35', '2026-04-23 06:02:35'),
(4, 2, 'Magister Ilmu Hukum', 'magister-ilmu-hukum', 'S2', 'youtube', 'https://youtu.be/OGCNIjS8_gg', NULL, 'Program Studi Magister Ilmu Hukum Universitas Trisakti (untuk selanjutnya disebut Prodi MIH) sebagai program studi yang menyelenggarakan pendidikan Strata 2, berdasarkan Surat Keputusan Direktur Jenderal Pendidikan Tinggi Nomor: 2609/D/T/2001 tanggal 6 Agustus 2001, sebagai respon atas komitmen Universitas Trisakti untuk selalu berperan aktif dalam mewujudkan sumber daya manusia Indonesia yang berkualitas di bidang hukum. Memperhatikan proses dan dinamika pembangunan berkelanjutan saat ini dan masa mendatang, maka diperlukan sumber daya manusia yang lebih berkualitas. Sehubungan dengan hal tersebut, dibutuhkan adanya pendidikan lanjutan yang dapat memberikan tambahan pengetahuan, ketrampilan, sikap dan pengalaman bagi para magister baik hukum maupun non hukum. Sesuai dengan keunggulan Fakultas Hukum Universitas Trisakti, khususnya ketersediaan sumber daya manusia di bidang Hukum Agraria, Hukum Bisnis dan Hukum Pidana, maka Prodi MIH menyediakan 3 (tiga) konsentrasi yaitu Konsentrasi Hukum Agraria, Konsentrasi Hukum Bisnis dan Konsentrasi Hukum Pidana. Dalam melaksanakan perannya, Prodi MIH  berpedoman pada visi dan misi Magister Hukum yang sesuai dengan visi dan misi Fakultas Hukum dan Universitas Trisakti.\r\n\r\nDalam pelaksanaannya Prodi MIH telah terakreditasi dari Badan Akreditasi Nasional Perguruan Tinggi Departeman Pendidikan Nasional Republik Indonesia Nomor: 016/BAN-PT/Ak-IV/S2/II/2006 Tanggal 02 Februari 2006 dengan Nilai C, di reakreditasi berdasarkan Surat Keputusan Badan Akreditasi Nasional Perguruan Tinggi Departeman Pendidikan Nasional Republik Indonesia Nomor: 001/BAN-PT/Ak-V/S2/I/2007 Tanggal 13 Januari 2007 dengan Nilai B dengan angka 4,5, kemudian di reakreditasi berdasarkan Surat Keputusan Badan Akreditasi Nasional Perguruan Tinggi Departeman Pendidikan Nasional Republik Indonesia Nomor: 007/BAN-PT/AK-X/S2/VI/2012 tanggal 29 Juni 2012 dengan Nilai B dengan angka 336. Kemudian di reakreditasi berdasarkan Surat Keputusan BAN-PT Nomor: 2235/SK/BAN-PT/Akred/M/VII/2017 dengan nilai B. Kemudian tahun 2023 dilakukan reakreditasi dan memperoleh nilai Baik berdasarkan Surat Keputusan BAN-PT Nomor: 9964/SK/BAN-PT/Ak.Ppj/M/I/2023.\r\n\r\nDalam proses pembelajaran saat ini program studi menerapkan kurikulum sesuai KKNI pada level 8, sebagaimana ditetapkan dalam Surat Penetapan Rektor Universitas Trisakti Nomor: 201.v/Ak.1.01/Usakti/R/VII/2015 tanggal 17 Agustus 2015. Kurikulum ini kemudian disempurnakan pada tahun 2019 yang dimuat dalam SK Rektor Nomor 1631/USAKTI/SKR/VIII/2019. Pada tahun 2023 kurikulum operasional diperbarui berdasarkan Standar Nasional Pendidikan Tinggi (SN Dikti) dengan menerapkan pembelajaran berbasis luaran (OBE), yang selalu mengikuti perkembangan ipteksen dan kebutuhan para pemangku kepentingan dalam dan luar negeri, memiliki ciri kearifan dan keunikan lokal, menumbuhkan jiwa kewirausahaan, peka terhadap Nilai-Nilai Pancasila, berpedoman pada Trikrama Trisakti serta kelestarian lingkungan hidup.', 'Dr. Dhany Rahmawan, S.H.,M.Hum', '1776926969_4d3c6197d959475ab45a.png', 'Assalamu’alaikum warahmatullahi wabarakatuh, Salam Sejahtera bagi kita semua, Om Swastiastu, Namo Buddhaya, Salam Kebajikan\r\n\r\n“The life of the law has not been logic; it has been experience.”\r\n— Oliver Wendell Holmes Jr.\r\n\r\nSelamat datang di Program Studi Magister Ilmu Hukum (MiH) Fakultas Hukum Universitas Trisakti — ruang akademik tempat hukum berpadu dengan refleksi, inovasi, dan keadilan.\r\n\r\nProdi MiH Universitas Trisakti memiliki visi untuk mengembangkan ilmu hukum yang rekonstruktif dan responsif, yang memandang hukum bukan sebagai sistem yang beku, tetapi sebagai ilmu yang hidup, dibentuk oleh pengalaman manusia, nilai etika, dan kemajuan teknologi. Kami berkomitmen melahirkan ilmuwan, praktisi, dan pembaru hukum yang berpikir kritis, bertindak etis, dan berkontribusi nyata bagi pembangunan hukum nasional dan global.\r\n\r\nKurikulum kami memadukan Hukum Rekonstruktif dan Hukum & Teknologi (AI dan Hukum Perbandingan), untuk memperkuat pemahaman mahasiswa terhadap hukum dalam konteks sosial, ekonomi, dan teknologi. Melalui riset yang mendalam, kolaborasi interdisipliner, serta jejaring akademik internasional, MiH menumbuhkan generasi Magister Hukum baru yang mampu menjembatani kearifan lokal dengan keunggulan global. Di tengah arus perubahan, kami meyakini bahwa mempelajari hukum berarti menerangi jalan menuju keadilan.\r\n\r\nBergabunglah bersama kami dan jadikan pengetahuan Anda bagian dari perjalanan panjang Indonesia menuju peradaban hukum yang lebih adil, bijak, dan manusiawi.', '2026-04-23 06:49:29', '2026-04-23 06:49:29'),
(5, 5, 'Arsitektur Lanskap', 'arsitektur-lanskap', 'S1', 'youtube', 'https://youtu.be/m1LfnwnWfEg?si=G50-JAdOBk27Ek2n', 'Arsitektur Lanskap merupakan Profesi yang menerapkan prinsip prinsip estetika dan ilmu pengetahuan kedalam perancangan, perencanaan, analisis dan pengelolaan  lingkungan alam dan lingkungan binaan seperti yang dikemukan oleh Internasional Fedaration of Landscape Architecture  (IFLA)', 'Jurusan/Prodi Arsitektur Lanskap merupakan pengembangan program Akademi Arsitektur Pertamanan (AKAP), yang diprakarsai oleh Presiden RI Ir. Soekarno dan direalisir oleh Dr. H. Soemarno Sosroatmodjo (Gubernur DKI  saat itu) melalui S.K. No. 012/DPRD-GR/62 tanggal 1 Oktober 1963. Di tahun 1970 AKAP-DCI diserahkan kepada Yayasan Trisakti dan berubah nama menjadi Akademi Arsitektur Pertamanan dan Perencanaan Kota (AKAPP) Trisakti dan pada Tahun 1973 AKAPP Trisakti menjadi Sekolah Tinggi Arsitektur Pertamanan Trisakti (STAPI).\r\n\r\nPada 18 Maret 1977 didirikan Fakultas Arsitektur Lansekap dengan 1 (satu) jurusan yaitu Arsitektur Lansekap, dan pada tahun 18 Februari 1985 menjadi FALTL.  dan mulai tahun 1991, status “Terdaftar” pada jurusan/program studi Arsitektur Lansekap meningkat menjadi “Diakui” dengan surat keputusan Menteri Pendidikan dan Kebudayaan No.073/0/1991 tertanggal 21 Pebruari 1991 dan selanjutnya pada tahun 1993 telah dapat ditingkatkan Statusnya menjadi “Disamakan” dengan SK. Dikti No.494/Dikti/Kep/1993 tanggal 16 Agustus 1993.\r\n\r\nDalam perkembangannya, Program Studi Arsitektur Lanskap, FALTL, Universitas Trisakti saat ini telah terakreditasi B berdasarkan Keputusan Badan Akreditasi Perguruan Tinggi Departemen Pendidikan Nasional-RI, SK. BAN-PT SK 3935/SK/BAN-PT/Akred/S/X/2019, yang akan berakhir pada tanggal 16 Oktober 2024. Keberadaan Program Studi Arsitektur Lanskap, FALTL, Universitas Trisakti diharapkan dapat menjadi pusat pendidikan arsitektur lanskap, serta menjamin terciptanya pembangunan berkelanjutan baik di Indonesia maupun secara global.', 'Dr. Rini Fitri, S.P., MSi.', '1776927317_4e4cd2b6631925ed76b7.jpg', 'Assalamualaikum dan salam sejahtera\r\n\r\nPuji syukur dipanjatkan atas Kehadirat Allah SWT, yang senantiasa melimpahkan Kebaikan serta Kasih Sayang-Nya kepada kita semua.\r\n\r\nSelamat Datang di Program Studi Arsitektur Lanskap, Fakultas Arsitektur Lanskap dan Teknologi Lingkungan Universitas Trisakti. Program Studi Arsitektur Lanskap menghargai semua kerja sama, prestasi dan pencapaian baik dalam bidang pengajaran, penelitian dan pengabdian kepada masyarakat yang telah dicapai selama ini.', '2026-04-23 06:55:17', '2026-04-23 06:55:17'),
(6, 5, 'Teknik Lingkungan', 'teknik-lingkungan', 'S1', 'image', NULL, 'Universitas Trisakti, merupakan satu-satunya perguruan tinggi swasta di Indonesia yang didirikan oleh Pemerintah Republik Indonesia pada tanggal 29 November 1965 melalui Surat Keputusan Menteri Perguruan Tinggi dan Ilmu Pengetahuan (PTIP) Nomor 014/dar tahun 1965 yang ditandatangani oleh Dr. Sjarif Thajeb. Tanggal 29 November ini kemudian ditetapkan sebagai hari kelahiran Universitas Trisakti.', 'Program Studi Teknik Lingkungan merupakan salah satu Program Studi di Fakultas Arsitektur Lanskap dan Teknologi Lingkungan, Universitas Trisakti. Program Studi ini berdiri pada tahun 1985 dengan SK pendirian No. 073/0/1985 tertanggal 18 Februari 1985 yang ditandatangani oleh Menteri Pendidikan dan Kebudayaan, dengan status terdaftar dan mulai beroperasi pada tahun 1986.\r\n\r\nDalam perkembangannya, Program Studi Teknik Lingkungan secara bertahap telah mampu meningkatkan statusnya yaitu :\r\nTahun 1992, berstatus Diakui\r\nTahun 1996, berstatus Disamakan\r\nTahun 1998, terakreditasi dengan peringkat B\r\nTahun 2000, terakreditasi dengan peringkat A\r\nTahun 2005, terakreditasi dengan peringkat B\r\nTahun 2010, terakreditasi dengan peringkat A\r\nTahun 2015, terakreditasi dengan peringkat A\r\nTahun 2020, terakreditasi dengan peringkat A\r\nTahun 2021, terakreditasi Internasional IABEE\r\nTahun 2021, terakreditasi dengan predikat UNGGUL\r\nTahun 2021, tersertifikasi ASEAN University Network-Quality Assurance (AUN-QA)\r\n\r\nProgram Studi Teknik Lingkungan FALTL, Universitas Trisakti saat ini telah terakreditasi UNGGUL berdasarkan Keputusan Badan Akreditasi Perguruan Tinggi Departemen Pendidikan Nasional-RI, SK. BAN-PT No. 9146/SK/BAN-PT/Akred-Itnl/S/VI/2021 pada tanggal 30 Juni 2021 dan berlaku hingga 31 Maret 2024 dan pada tanggal 18 Maret 2021 telah terakreditasi Internasional General Accreditation dari Indonesia Accreditation Board for Engineering Education (IABEE). Disamping itu program studi Teknik Lingkungan juga telah tersertifikasi Internasional ASEAN University Networking-Quality Assurance pada tanggal 19 Februari 2021 dengan predikat “adequate as expected”.\r\n\r\nKeberadaan Program Studi Teknik Lingkungan, FALTL, Universitas Trisakti diharapkan dapat menjadi pusat pendidikan teknik lingkungan yang unggul serta menjamin terciptanya pembangunan berkelanjutan baik di Indonesia maupun regional Asia Tenggara.', 'Astari Minarti, ST., M.Sc', '1776927780_50ed791651f1707628e3.jpg', 'Permasalahan lingkungan global yang dihadapi pembangunan nasional saat ini sangat beragam, mulai dari permasalahan domestik (ketersediaan air bersih, sampah, drainase, air limbah domestik), kerusakan dan berkurangnya sumberdaya lingkungan (kerusakan atmosfir, kerusakan lapisan ozon, kerusakan dan berkurangnya sumberdaya hutan, berkurangnya keanekaragaman hayati, pencemaran dan berkurangnya sumber daya air) hingga penurunan kualitas hidup.\r\n\r\nAgenda pembangunan berkelanjutan yang baru dibuat untuk menjawab tuntutan kepemimpinan dunia dalam mengatasi kemiskinan, kesenjangan, dan perubahan iklim dalam bentuk aksi nyata. Agenda 2030 terdiri dari 17 Tujuan Pembangunan Berkelanjutan (SGD) atau Tujuan Global, yang akan menjadi tuntunan kebijakan dan pendanaan untuk 15 tahun ke depan (2030). Tujuan Pembangunan Berkelanjutan atau dalam bahasa Inggris dikenal sebagai Sustainable Development Goals disingkat dengan SDGs adalah 17 tujuan dengan 169 capaian yang terukur dan tenggat yang telah ditentukan oleh PBB sebagai agenda dunia pembangunan untuk kemaslahatan manusia dan planet bumi.', '2026-04-23 07:03:00', '2026-04-23 07:03:00'),
(7, 5, 'Perencanaan Wilayah dan Kota', 'perencanaan-wilayah-dan-kota', 'S1', 'image', '', 'Universitas Trisakti, merupakan satu-satunya perguruan tinggi swasta di Indonesia yang didirikan oleh Pemerintah Republik Indonesia pada tanggal 29 November 1965 melalui Surat Keputusan Menteri Perguruan Tinggi dan Ilmu Pengetahuan (PTIP) Nomor 014/dar tahun 1965 yang ditandatangani oleh Dr. Sjarif Thajeb. Tanggal 29 November ini kemudian ditetapkan sebagai hari kelahiran Universitas Trisakti.', 'Jurusan Teknik Planologi dengan program studi Perencanaan Wilayah dan Kota di Universitas Trisakti berada dibawah naungan Fakultas Arsitektur Lansekap dan Teknologi Lingkungan (FALTL) disamping dua Jurusan lainnya yaitu Jurusan Arsitektur Lansekap dan Jurusan Teknik Lingkungan. Jurusan baru ini merupakan program Strata 1 (S1), mulai dibuka pada tahun akademik 1996/1997 sesuai dengan SK. No. 377/DIKTI/KEP/1996, dan mendapatkan status Terakreditasi dengan peringkat C pada tahun akademik 2002/2003 sesuai dengan Keputusan Badan Akreditasi Nasional Perguruan Tinggi (BAN-PT) Departemen Pendidikan Nasional RI Nomor 016/BAN-PT/AK-VII/S1/VII/2003. pada tahun 2007/2008 Jurusan Teknik Planologi telah mampu meningkatkan statusnya yaitu mendapatkan Akreditasi dengan peringkat B sesuai dengan Keputusan Badan Akreditasi Nasional Perguruan Tinggi (BAN-PT) Departemen Pendidikan Nasional RI Nomor 010/BZN-PT/AK-XI/S1/VI/2008. Kemudian pada tahun 2018/2019 Jurusan Teknik Planologi telah mampu meningkatkan statusnya kembali dengan mendapatkan Akreditasi dengan peringkat A sesuai dengan Keputusan Badan Akreditasi Nasional Perguruan Tinggi (BAN-PT) Departemen Pendidikan Nasional RI Nomor 2731/SK/BAN-PT/Akred/S/X/2018. Di tahun 2024 Jurusan Teknik Planologi telah mampu meningkatkannya kembali statusnya dengan mendapatkan Akreditasi dengan peringkat Unggul sesuai dengan Keputusan Badan Akreditasi Nasional Perguruan Tinggi (BAN-PT) Departemen Pendidikan Nasional RI Nomor 553/SK/BAN-PT/AK.KP/S/II/2024.\r\n\r\nPembukaan jurusan ini didasarkan pada pemikiran bahwa kebutuhan perencana fisik di sektor pemerintahan makin meningkat sejalan dengan rencana (saat itu) otonomi daerah dan makin terbukanya peluang pekerjaan di sektor swasta.  Selain itu, berdasarkan data yang ada prosentase lulusan planologi dari Universitas lain yang bekerja di sektor swasta masih rendah yang diperkirakan karena kualitas yang ada belum mampu untuk bisa memenuhi tuntutan perusahaan yang berorientasi bisnis, kurang memiliki pengetahuan yang rinci tentang pekerjaan detail, serta kurang memiliki pengetahuan dan wawasan politik.\r\n\r\nJurusan Teknik Planologi, FALTL, Universitas Trisakti dikembangkan dengan menitik beratkan pada masalah “Urban Development Planning Issues” serta mengharapkan lulusannya mempunyai “sense of public services and business”. Untuk memberikan nilai tambah tersebut, selain kurikulum inti yang baku, para mahasiswa juga diberikan wawasan dan pengetahuan yang cukup mengenai bidang manajemen, ekonomi dan sosial khususnya yang berhubungan dengan perencanaan fisik.', 'Anindita Ramadhani, S.T., M.T', '1776928112_5d2aa1045d0240e7d7df.jpg', 'Assalamualaikum Warahmatullahi Wabarakatuh.\r\n\r\nSelamat datang di Program Studi Perencanaan Wilayah dan Kota Teknik Planologi, Universitas Trisakti.\r\n\r\nPerkembangan perkotaan yang semakin lama semakin pesat menimbulkan berbagai permasalahan fisik ruang kota, masalah sosial dan ekonomi, yang cenderung berdampak negatif terhadap kehidupan kota. Saat ini saja telah kita rasakan bersama lingkungan perkotaan yang kondisi lingkungannya sudah sangat tercemar, kemacetan lalu lintas yang sudah sangat parah, prasarana dan sarana publik yang tidak memadai, tidak nyaman secara estetik, berbagai bencana alam terjadi, berbagai masalah sosial muncul; yang secara keseluruhan menyebabkan kehidupan kota dan penduduknya menjadi tidak produktif, bahkan cenderung kontra produktif.\r\n\r\nJurusan Teknik Planologi, Program Studi Perencanaan Kota dan Wilayah Usakti adalah bidang studi yang mempelajari dan mendalami perencanaan dan menejemen pembangunan perkotaan dan wilayah yang menghasilkan ahli-ahli yang mampu berkiprah di dalam upaya mengatasi masalah-masalah perkotaan dan wilayah tersebut.\r\n\r\nLulusan Program Studi Perencanaan Kota dan Wilayah Usakti dibekali dengan berbagai pengetahuan dan ketrampilan di dalam menyusun tata ruang perkotaan dan wilayah dan mengelola pembangunan kota dan wilayah. Dengan demikian, selaras dengan perkembangan perkotaan dan wilayah berikut berbagai permasalahan yang timbul akibat perkembangan tersebut, lulusan Program Studi Perencanaan Kota dan Wilayah akan selalu dibutuhkan oleh sektor pemerintah (pusat dan daerah), swasta (konsultan, appraisal, perbankan, dsb), pusat-pusat penelitian dan kajian perkotaan, serta perguruan tinggi.\r\n\r\nSaat ini, alumni Jurusan Teknik Planologi Usakti sudah bekerja di berbagai bidang, dan ternyata mereka mudah terserap ke berbagai lapangan kerja. Semenjak lulus, waktu tunggu mereka untuk memperoleh pekerjaan tidak lebih dari 2 bulan. Kamipun memperoleh informasi, bahwa mereka cukup berprestasi dan sangat dihargai di tempat mereka bekerja. Mengingat lulusan Jurusan Teknik Planologi dari berbagai perguruan tinggi seluruh Indonesia relatif masih sedikit dibandingkan dengan lapangan pekerjaan yang masih terbuka sangat luas, kami mengajak para orang tua untuk menyekolahkan putra-putrinya di Jurusan Teknik Planologi Usakti yang akan menjanjikan masa depan yang cerah.\r\n\r\nSemoga Allah SWT, selalu melimpahkan rahmat dan perlindungan bagi kita semua.', '2026-04-23 07:08:32', '2026-04-23 07:09:37'),
(8, 4, 'Desain Interior', 'desain-interior', 'S1', 'image', '1776928289_7d837dfd040ee77343c9.jpg', 'Program Studi Desain Interior Universitas Trisakti bertujuan untuk menghasilkan lulusan yang andal yang memiliki kemampuan intelektual, profesional, inovatif, menghargai, mengangkat serta melestarikan seni tradisi dan kearifan lokal tanpa melupakan standar-standar internasional yang berlaku. Kurikulum program studi Desain Interior selalu mengikuti perkembangan industri Desain Interior dengan melalui proses evaluasi rutin yang dilaksanakan bersama para stakeholder/ pengguna lulusan termasuk dengan asosiasi profesi HDII (Himpunan Desainer Interior Indonesia). Dengan terjalinnya kerjasama, Mahasiswa memperoleh kesempatan lebih luas untuk terlibat dalam kegiatan-kegiatan nasional maupun internasional, seperti pameran, seminar, konferensi, dan lainnya sebagai salah satu bekal sebelum terjun ke dunia profesional.\r\n\r\nProgram Studi Desain Interior Universitas Trisakti bertujuan untuk:\r\n\r\nMenghasilkan lulusan yang andal yang memiliki kemampuan intelektual, profesional, inovatif, menghargai, mengangkat serta melestarikan seni tradisi dan kearifan lokal tanpa melupakan standar-standar internasional yang berlaku.\r\n\r\nKurikulum program studi Desain Interior selalu mengikuti perkembangan industri Desain Interior dengan melalui proses evaluasi rutin yang dilaksanakan bersama para stakeholder/ pengguna lulusan termasuk dengan asosiasi profesi HDII (Himpunan Desainer Interior Indonesia).\r\n\r\nDengan terjalinnya kerjasama, Mahasiswa memperoleh kesempatan lebih luas untuk terlibat dalam kegiatan-kegiatan nasional maupun internasional, seperti pameran, seminar, konferensi, dan lainnya sebagai salah satu bekal sebelum terjun ke dunia profesional.', '1969	BERDIRI SEBAGAI JURUSAN ARSITEKTUR INTERIOR DIBAWAH DEPARTEMEN\r\nFAKULTAS TEKNIK SIPIL DAN PERENCANAAN.\r\n \r\n1970	JURUSAN DESAIN INTERIOR SECARA KHUSUS MULAI BERJALAN.\r\n \r\n2002	MENDAPAT AKREDITASI B\r\n\r\n2005	MENDAPAT AKREDITASI A', NULL, NULL, NULL, '2026-04-23 07:11:29', '2026-04-23 07:12:23'),
(9, 3, 'Pendidikan Dokter Gigi', 'pendidikan-dokter-gigi', 'S1', 'image', '1776928567_424107bf42d1128d838b.jpg', NULL, NULL, 'drg. Ade Prijanti, Sp. KG(K), PhD', '1776928567_8dae58a092996a10d642.png', 'Assalamu’alaikum warahmatullahi wabarakatuh,\r\n\r\nPuji syukur kehadirat Allah SWT atas segala rahmat dan hidayah-Nya sehingga Program Studi Pendidikan Dokter Gigi Universitas Trisakti  (PS Pendidikan Dokter Gigi FKG Usakti) dapat menjadi bagian dari pendidikan tinggi yang menghasilkan Sarjana Kedokteran Gigi yang andal dan berkualitas untuk memberikan pelayanan terbaik kepada masyarakat dan bangsa Indonesia.\r\n\r\nFakultas Kedokteran Gigi Universitas Trisakti juga tercatat menduduki rangking ke-6 sebagai Fakultas Kedokteran Gigi terbaik di Indonesia menurut Scimago Insitutions Rankings tahun 2021. Hal ini sekaligus mengukuhkan posisi FKG Usakti sebagai FKG swasta terbaik di Indonesia. Mendukung hal tersebut, berdasarkan Surat Keputusan LAM-PTKes Nomor: 0678/LAM-PTKes/Akr/Sar/XII/2020, 18 Desember 2020, PS Pendidikan Dokter Gigi FKG Usakti “Terakreditasi dengan Peringkat A”\r\n\r\nKurikulum PS Pendidikan Dokter Gigi FKG Usakti berpedoman pada Standar Kompetensi Dokter Gigi Indonesia (SKDGI) yang disahkan oleh Konsil Kedokteran Gigi (KKI) tahun 2015 yang merupakan acuan standar dalam penyelenggaraan pendidikan kedokteran gigi di Indonesia selain Standar Nasional Pendidikan Tinggi yang dikeluarkan oleh PERMENDIKBUD no 3 tahun 2020.  Kurikulum pada tahap Program Studi Akademik (Strata 1) FKG Usakti dilaksanakan dengan cara kombinasi antara tatap muka dan diskusi, seminar dengan mengedepankan Student Centered Learning (SCL) melalui metode pembelajaran Cooperative and Collaborative Learning System yang merupakan metode pembelajaran yang lebih mengarahkan mahasiswa kepada active learning.\r\n\r\nPS Pendidikan Dokter Gigi FKG Usakti didukung dengan fasilitas perkuliahan dan praktikum yang modern dan sangat memadai. Di samping itu, tersedia 4 laboratorium penelitian yaitu: Lab. BioCore, Lab OpadCore, Lab MiCore dan Lab DMTCore, yang akan menunjang tugas akhir para mahasiswanya. PS Pendidikan Dokter Gigi FKG Usakti didukung oleh Sistem Informasi yang menunjang kelancaran pendidikan serta pengajaran yang digunakan oleh Program Studi Pendidikan Dokter Gigi  FKG Usakti  yang terdiri dari: Student Information System ( SIS), Sistem Informasi Perpustakaan  dan Sistem e-Jurnal.\r\n\r\nAkhir kata pencapaian yang telah diperoleh merupakan tantangan untuk  kita semua agar senantiasa meningkatkan kualitas diri serta  tidak boleh berpuas diri sehingga target selalu dicanangkan agar mampu tetap berkibar sebagai PTS Swasta terbaik. Semoga Allah SWT selalu meridhoi Langkah kita Bersama.\r\n\r\nWassalamu’alaikum warahmatullahi wabarakatuh', '2026-04-23 07:16:07', '2026-04-23 07:16:07'),
(10, 4, 'Desain Produk', 'desain-produk', 'S1', 'image', '1776928727_14eb9548419ac83bed65.jpg', 'Sebuah program studi sarjana (S1) yang mendidik mahasiswa menjadi desainer produk profesional yang mampu:\r\n\r\n1. Merancang produk-produk inovatif dan bernilai guna tinggi.\r\n2. Mengintegrasikan aspek Bisnis, estetika, ergonomi, teknik produksi, dan lingkungan.\r\n3. Menjawab kebutuhan masyarakat dan industri melalui pendekatan desain yang kreatif dan bertanggung jawab.\r\n4. Berorientasi pada Produk yang Berwawasan Bisnis, kearifan lokal serta daya saing global.\r\n\r\nProfesi Desain Produk :\r\n\r\n- Desain produk kebutuhan sehari-hari (Merancang Elektronik, furniture, alat rumah tangga, packaging, dll)\r\n- Desain transportasi & otomotif (Merancang kendaraan)\r\n- Desain alat bantu (Merancang alat untuk keperluan medical product, tools)\r\n- Konsultan Desain Produk\r\n- Desainer Kerajinan (Merancang produk yang memanfaatkan tenaga pengrajin)\r\n- Dosen dan pengajar dalam ilmu Desain Produk\r\n- Desainer fesyen (Merancang produk pakaian dan perlengkapannya dalam skala Manufaktur)', 'Program Studi Desain Produk merupakan bagian dari Jurusan Desain pada Fakultas Seni Rupa dan Desain Universitas Trisakti. Program Studi Desain Produk telah mengalami perjalanan panjang sejak tahun 1969 dalam mengikuti bidang Ilmu Pengetahuan dan Teknologi yang berjalan begitu cepat. Hal ini mewajibkan Desain Produk untuk terus membenahi diri, meningkatkan kualitas dalam merebut simpati dan kepercayaan masyarakat. Suatu hasil desain akan disebut berhasil bilamana produknya bisa memenuhi kepentingan dari banyak pihak terkait, dari mulai konsumen, pedagang, eksportir dan produsen. Hal ini tentunya akan menemui banyak kendala, pekerjaan penciptaan suatu produk adalah bukan suatu pekerjaan yang sederhana. Tugas ini hanya bisa dilakukan dengan baik oleh desainer yang profesional dan ahli dalam bidangnya. Desain Produk harus mampu menjembatani berbagai kepentingan dari semua pihak terkait dan mengolahnya menjadi suatu rancangan yang utuh dan terpadu. Sebagaimana kita ketahui, banyak di antara desain produk yang ada merupakan hasil rancangan yang bernuansa teknologi masa depan tetapi tidak menutup kemungkinan untuk pengembangan produk tradisional.\r\n\r\nDalam materi perkuliahan, pengembangan desain tradisional tetap dipertahankan karena hal ini merupakan ciri khas yang dimiliki oleh bangsa Indonesia. Peningkatan dan pengendalian mutu Desain Produk terus dilakukan dengan didukung sarana dan prasarana yang memadai berupa; perpustakaan, praktek bengkel, lab.komputer, studio T.A dan lain-lain. Peningkatan kemampuan staf akademik pada Desain Produk berupa peningkatan jenjang pendidikan, mengikuti kursus, seminar dan lain-lain. Pengembangan wawasan bagi mahasiswa dilakukan dengan melakukan kerja profesi pada industri terkait, kunjungan pada industri, studi banding dengan lembaga pendidikan seprofesi, mengikuti seminar dan lain-lain. Lulusan dari program studi Desain Produk berprofesi sebagai wiraswastawan desain, pendididkan tinggi disain, disainer professional, pemerintahan dan perusahaan multi nasional. Sesuai dengan Visi, Misi, Sasaran dan Tujuan Desain Produk Fakultas Seni Rupa Dan Desain Universitas Trisakti di masa mendatang harus mampu menghadapi kompetisi dengan mitra pendidikan Desain Produk di dalam negeri dan luar negeri di negaranya sendiri maupun yang membuka cabang di Indonesia.', NULL, NULL, NULL, '2026-04-23 07:18:47', '2026-04-23 07:18:47'),
(11, 4, 'Desain Komunikasi Visual', 'desain-komunikasi-visual', 'S1', 'image', '1776929264_20d3da52889459d61663.png', 'Program Studi Desain Komunikasi Visual telah Terakreditasi A oleh BAN-PT. Pemberlakuan Kurikulum Dikti 2015 berbasis Kerangka Kualifikasi Nasional Indonesia (KKNI) yang disahkan Rektor pada tanggal 17 Agustus 2015 memberlakukan 2 (dua) pembagian konsentrasi yaitu Konsentrasi Desain Grafis dan Konsentrasi Multimedia.', 'Pada tahun 1969 Fakultas Teknik Universitas Trisakti membuka departemen baru yaitu Departemen Seni Rupa, dengan Drs. Soekarno sebagai Kepala Departemen. Departemen Seni Rupa memiliki 3 (tiga) Spesialisasi Keahlian yaitu Arsitektur Interior, Desain Industri, dan Seni Lukis dengan status “Terdaftar”. Selanjutnya pada tahun 1978 menjadi Jurusan Desain dalam lingkup Fakultas Teknik Sipil dan Perencanaan, dengan salah satu Program Pengutamaan Studi Desain Grafis. Kelulusan pertama Departemen Seni Rupa adalah pada tahun 1980.\r\n\r\nProgram Pengutamaan Studi Desain Grafis kemudian berubah nama menjadi Program Studi Desain Grafis pada tahun 1983. Status yang sebelumnya “Baru” menjadi “Terdaftar”. Pada tahun 1992 statusnya meningkat menjadi “Disamakan”, mengikuti perkembangan kemajuan di bidang ilmu pengetahuan dan teknologi. Pada tahun 1996, dibentuk Fakultas Seni Rupa dan Desain yang memiliki Jurusan Desain dan Jurusan Seni Rupa, dengan Program Studi Desain Komunikasi Visual berada di bawah naungan Jurusan Desain.\r\n\r\nPada tahun akademik 1997/1998 sesuai dengan keputusan Badan Akreditasi Nasional (BAN) Perguruan Tinggi Departemen Pendidikan dan Kebudayaan Republik Indonesia Nomor: 001/BPN-PT/AK/I/VIII/1998 tanggal 11 Agustus 1998 bahwa jurusan Disain telah terakreditasi dengan nilai ”B”, pada tahun 2000 diadakan penilaian kembali dengan peringkat nilai “B”. Program Studi Desain Komunikasi Visual terus membenahi diri dan meningkatkan kualitas diri dalam menghadapi perkembangan Ilmu Pengetahuan Teknologi dan Seni di masa mendatang. Pada tahun 2006 penilaian oleh BAN PT Nomor 020/BAN-PT/Ak-X/S1/XII/2006 memperoleh peringkat nilai akreditasi  ”A”. Selanjutnya, pada akreditasi tahun 2012 oleh BAN PT dengan surat keputusan No. 028/BAN-PT/Ak-SURV-III/S1/VII/2012 tanggal 19 Juli 2012, Program Studi Desain Komunikasi Visual berhasil mempertahankan peringkat nilai akreditasi ”A”. Predikat lain adalah ”Indonesia Best School of Visual Communication Design, A Accreditation Category” dari Mix Marketing Communication Magazine yang didapatkan berturut-turut pada tahun 2013, 2014, dan 2015.\r\n\r\nPeringkat akreditasi saat ini adalah Akreditasi ”A” berdasarkan surat keputusan BAN PT No. 2847/SK/BAN-PT/Akred/S/XII/2016 tanggal 1 Desember 2016. Pemberlakukan Kurikulum Dikti 2015 berbasis Kerangka Kualifikasi Nasional Indonesia (KKNI) yang disahkan Rektor pada tanggal 17 Agustus 2015 memberlakukan 2 (dua) pembagian konsentrasi yaitu Konsentrasi Desain Grafis dan Konsentrasi Multimedia.', NULL, NULL, NULL, '2026-04-23 07:22:17', '2026-04-23 07:27:44'),
(12, 3, 'Profesi Dokter Gigi', 'profesi-dokter-gigi', 'Profesi', 'image', '1776928996_6c311a928fa4ae025c37.jpg', NULL, NULL, 'Dr. drg. Tri Putriany Agustin, Sp. KGA.', '1776982472_7c314d4ee2647aeac72a.jpg', 'Assalamu’alaikum warahmatullahi wabarakatuh,\r\n\r\nPuji syukur kehadirat Allah SWT atas segala rahmat dan hidayah-Nya sehingga Program Studi Pendidikan Profesi Dokter Gigi Universitas Trisakti  (PS Pendidikan Profesi FKG Usakti) dapat menjadi bagian dari pendidikan tinggi yang menghasilkan dokter gigi yang handal dan berkualitas untuk memberikan pelayanan terbaik kepada masyarakat dan bangsa Indonesia.   Lulusan dokter gigi luaran PS  Pendidikan Profesi FKG Usakti mampu bersaing dengan lulusan dokter gigi dari Institusi Pendidikan Dokter Gigi lain, terbukti dari capaian hasil Uji Kompetensi Mahasiswa Program Profesi Dokter Gigi yaitu masuk 10 besar dalam kurun waktu 5 tahun berturut-turut.\r\n\r\nFakultas Kedokteran Gigi Universitas Trisakti juga tercatat menduduki rangking ke-6 sebagai Fakultas Kedokteran Gigi terbaik di Indonesia menurut Scimago Insitutions Rankings tahun 2021. Hal ini sekaligus mengukuhkan posisi FKG Usakti sebagai FKG swasta terbaik di Indonesia.\r\n\r\nKurikulum Pendidikan Profesi Dokter Gigi FKG Usakti berpedoman pada Standar Kompetensi Dokter Gigi Indonesia (SKDGI) yang disahkan oleh Konsil Kedokteran Gigi (KKI) tahun 2015 yang merupakan acuan standar dalam penyelenggaraan pendidikan kedokteran gigi di Indonesia selain Standar Nasional Pendidikan Tinggi yang dikeluarkan oleh PERMENDIKBUD no 3 tahun 2020.  Program Pendidikan Profesi Dokter Gigi memiliki level kompetensi 7 sesuai dengan Kerangka Kualifikasi Nasional Indonesia (KKNI)  sehingga nantinya seorang lulusan pendidikan profesi dokter gigi dapat bekerja sebagai care provider, decision maker, communicator, community leader, manager, researcher/lecturer,   creator dan innovator.\r\n\r\nPengajaran dan pendidikan profesi dokter gigi dilakukan oleh 124 dosen tetap yang memiliki spesialisasi dan keahlian serta pengalaman praktek kedokteran gigi yang luas. Metode pembelajaran pada PS Pendidikan Profesi  dijalankan dengan case-based learning serta tutorial akademik berupa chair side teaching, case base discussion, dan journal reading.\r\n\r\nPendidikan profesi dokter gigi di FKG Usakti didukung dengan fasilitas yang sangat memadai di Rumah Sakit Gigi dan Mulut Pendidikan (RSGM-P) diantaranya 135 dental unit yang tersebar di klinik integrasi, 18 ruang perawatan negative pressure room, instalasi radiologi, farmasi, ruang bedah mayor, serta laboratorium dental. Untuk memperkuat administrasi dan penginputan data didukung oleh Sistem Informasi Akademik Mahasiswa Profesi (SIAPP) dan Sistem Informasi Rumah Sakit (SIMRS).   Dengan fasilitas tersebut memunculkan optimisme bahwa Program Studi Pendidikan Profesi Dokter Gigi FKG Usakti dapat memberikan kontribusi terbaik dan mampu bersaing saat ini maupun di masa yang akan datang.\r\n\r\nAkhir kata,pencapaian yang telah diperoleh merupakan tantangan untuk  kita semua agar senantiasa meningkatkan kualitas diri serta  tidak boleh berpuas diri sehingga target selalu dicanangkan agar mampu tetap berkibar sebagai PTS Swasta terbaik. Semoga Allah SWT selalu meridhoi Langkah kita Bersama.\r\n\r\nWassalamu’alaikum warahmatullahi wabarakatuh', '2026-04-23 07:23:16', '2026-04-23 22:14:32');
INSERT INTO `prodi` (`id`, `id_fakultas`, `nama`, `slug`, `jenjang`, `bg_tipe`, `bg_value`, `tentang`, `sejarah`, `nama_kaprodi`, `foto_kaprodi`, `sambutan_kaprodi`, `created_at`, `updated_at`) VALUES
(13, 3, 'Magister Ilmu Kedokteran Gigi', 'magister-ilmu-kedokteran-gigi', 'S2', 'image', '1776929515_edbdc26f7483b214d896.jpeg', 'Pendirian Program Studi Magister Ilmu Kedokteran Gigi (PS MIKG) dimulai sejak tahun 1998 dengan masa studi 4 semester dan hingga kini telah menghasilkan lulusan yang tersebar di seluruh Indonesia dan bekerja sesuai dengan bidang ilmu. Izin penyelenggaraan PS MIKG pada Universitas Trisakti sesuai Keputusan Dirjen Dikti No. 370/DIKTI/Kep/1998 tanggal 14 Oktober 1998. Dalam menghadapi persaingan di era globalisasi, baik bidang informasi, industri maupun ilmu jasa kesehatan maka tidak ada jalan lain kecuali dengan meningkatkan kualitas sumber daya manusia khususnya di bidang Kedokteran Gigi. Sejak tahun 2021 PS MIKG terdapat 2 (dua) peminatan yaitu Peminatan Manejemen Pelayanan Kesehatan Gigi dan Mulut dan Ilmu Kedokteran Gigi Dasar dan Klinis. Kedua unsur ini merupakan suatu kesatuan yang utuh. Salah satu tujuan PS MIKG FKG Usakti adalah sebagai pusat riset dengan mengembangkan sumber daya dan iklim akademik yang dapat mendukung karya riset untuk menghasilkan Iptek dan karya ilmiah inovatif di bidang kedokteran gigi.', 'Pendirian Program Studi Magister Ilmu Kedokteran Gigi (PS MIKG) dimulai sejak tahun 1998 dengan masa studi 4 semester dan hingga kini telah menghasilkan lulusan yang tersebar di seluruh Indonesia dan bekerja sesuai dengan bidang ilmu. Izin penyelenggaraan PS MIKG pada Universitas Trisakti sesuai Keputusan Dirjen Dikti No. 370/DIKTI/Kep/1998 tanggal 14 Oktober 1998. Dalam menghadapi persaingan di era globalisasi, baik bidang informasi, industri maupun ilmu jasa kesehatan maka tidak ada jalan lain kecuali dengan meningkatkan kualitas sumber daya manusia khususnya di bidang Kedokteran Gigi.\r\nSejak tahun 2021 PS MIKG terdapat 2 (dua) peminatan yaitu Peminatan Manejemen Pelayanan Kesehatan Gigi dan Mulut dan Ilmu Kedokteran Gigi Dasar dan Klinis. Kedua unsur ini merupakan suatu kesatuan yang utuh. Jika pada pemberian pelayanan kedokteran gigi dijumpai suatu masalah yang tidak dapat dipecahkan dengan pengetahuan dan pengalaman yang tersedia, jawabannya dapat dicari melalui Ilmu Kedokteran Gigi. Sebaliknya, Ilmu Kedokteran Gigi harus mampu memberi petunjuk mengenai tindakan yang sebaiknya dilakukan dalam pemberian pelayanan kedokteran gigi. Petunjuk itu diperoleh melalui pengetahuan ilmiah yang telah tersedia atau melalui pengetahuan baru hasil riset ilmiah tentang masalah yang ditemukan dan belum terpecahkan oleh pelayanan kedokteran gigi.\r\nPada dasawarsa terakhir, terlihat kecenderungan di dunia ilmu kedokteran gigi internasional untuk lebih meningkatkan pemahaman terhadap Ilmu Kedokteran Gigi Dasar dan Klinis serta Manejemen Pelayanan Kesehatan Gigi dan Mulut. Hal ini diperlukan karena kebutuhan untuk memperoleh jawaban atas masalah-masalah klinis yang memerlukan riset. Sehubungan dengan  hal tersebut, salah satu tujuan PS MIKG FKG Usakti adalah sebagai pusat riset dengan mengembangkan sumber daya dan iklim akademik yang dapat mendukung karya riset untuk menghasilkan Iptek dan karya ilmiah inovatif di bidang kedokteran gigi.\r\nProgram Studi ini menyajikan 38 sks serta lama studi 4 semester. Pelaksanaan pendidikan mengutamakan kemandirian meliputi diskusi kelompok, kerja laboratorium, seminar, journal reading, publikasi karya tulis ilmiah, riset dan tesis.\r\n\r\nDaya Tarik PS MIKG FKG Usakti:\r\n- Status Akreditasi Program Studi: Unggul\r\n- Status Akreditasi FKG Usakti: A\r\n- Status akreditasi Universitas Trisakti: A\r\n- Prospek peluang kerja: sebagai akademisi, manajer pengelolaan pelayanan medis ataupun non-medis, dunia media/jurnalisme (sebagai pengisi konten kesehatan gigi dan mulut) dan peneliti.\r\n- Lulusan PS MIKG dapat melanjutkan ke Program Pendidikan Dokter Gigi Spesialis atau ke Jenjang S3.\r\n- Kualitas/kualifikasi dosen: lulusan S2/Spesialis, Konsultan dan S3 dari universitas ternama di dalam dan luar negri. Memiliki 9 Guru Besar.\r\n- Waktu kuliah: terjadwal dan terstruktur dengan jelas.\r\n- Jenjang Pendidikan sesuai Kerangka Kualifikasi Nasional Indonesia (KKNI)\r\n- Fasilitas gedung, ruang kuliah, ruang perpustakaan, kantin dan ruang ibadah memadai.\r\n- Memiliki Laboratorium Penelitian: BioCore, MiCore, OpadCore dan DMTCore.\r\n\r\nSeleksi Mahasiswa Baru PS MIKG\r\nSistem rekrutmen peserta Program Studi MIKG adalah sesuai Buku Pedoman Penyelenggaraan Pendidikan Universitas Trisakti  sebagai berikut :\r\n\r\nPersyaratan Administrasi, calon peserta wajib menyerahkan :\r\n- Salinan ijazah Sarjana Kedokteran Gigi / dokter gigi / sarjana rumpun ilmu Kesehatan  lulusan Perguruan tinggi Dalam Negeri yang terakreditasi.\r\n- Untuk lulusan luar negeri, menyerahkan salinan ijazah Sarjana Kedokteran Gigi / dokter gigi luar negeri yang telah disahkan Kemenristek Dikti\r\n- Lulus Tes Potensial Akademik, test keterampilan dan test penelaahan jurnal.\r\n- Hasil TOEFL dengan nilai minimal 500.\r\n- Surat keterangan berbadan sehat dan tidak buta warna.\r\n- Rekomendasi dari dosen, atasan langsung.\r\nProsedur Seleksi\r\n\r\nTes Akademik, menguji pengetahuan calon mahasiswa baru dalam bidang kedokteran gigi.\r\nPenelaahan Jurnal\r\nWawancara\r\n', 'Dr. drg. M. Ihsan Rizal M.Kes.', '1776929515_541d7c5b83f20c016143.png', 'Rekan-rekan yang terhormat,\r\n\r\nMerupakan suatu kehormatan bagi kami untuk memberi sambutan mengenai Program Studi Magister Ilmu Kedokteran Gigi (PS MIKG) di Universitas Trisakti (Usakti). Sebagai Kepala Program Studi, saya bangga berbagi dengan Anda berbagai manfaat dan peluang yang ditawarkan program kami kepada mahasiswa yang ingin melanjutkan pendidikan dan karier mereka ke tingkat lebih lanjut.\r\n\r\nProgram kami disiapkan untuk membekali mahasiswa dengan pengetahuan dan keterampilan lanjutan di bidang kedokteran gigi. Pendidikan adalah proses seumur hidup, dan program kami bertujuan untuk membekali mahasiswa kami dengan perkembangan terbaru dalam ilmu kedokteran gigi, teknologi, dan penelitian. Kami percaya bahwa penelitian adalah komponen penting dari kemajuan ilmu kedokteran gigi, dan program kami memberi mahasiswa kesempatan untuk melakukan penelitian. Kami memiliki fasilitas dan peralatan penelitian canggih yang memungkinkan mahasiswa kami untuk mengeksplorasi dan menemukan teknik serta teknologi baru di bidang kedokteran gigi.\r\n\r\nKurikulum kami dirancang untuk memenuhi kebutuhan mahasiswa yang ingin mengejar karir di bidang kedokteran gigi atau memajukan karir mereka yang sudah ada. Komitmen kami dalam penyelenggaraan pendidikan berstandar internasional, namun PS MIKG Usakti tetap berpedoman kepada Standar Kompetensi Dokter Gigi Indonesia. Hal tersebut menghasilkan sebuah kurikulum yang komprehensif dan bermutu tinggi dengan luaran yang terukur.\r\n\r\nKami memiliki tim pengajar yang berkualifikasi tinggi dan berpengalaman yang berkomitmen untuk memberikan pendidikan berkualitas kepada mahasiswa kami. Mereka membawa pengalaman bertahun-tahun dalam penelitian, pengajaran, dan praktik klinis serta memastikan bahwa mahasiswa kami berhasil dalam upaya akademik dan profesional.\r\n\r\nPS MIKG diharapkan menghasilkan lulusan yang bertakwa kepada Tuhan Yang Maha Esa dan mampu menunjukkan sikap religius serta menjunjung tinggi nilai kemanusiaan dalam menjalankan tugas berdasarkan agama, moral, etika, disiplin dan taat hukum. Lulusan program  studi ini dapat bekerja sebagai dosen/tenaga pendidik, peneliti, ahli laboratorium, manajer/pengelola pusat penelitian atau laboratorium, serta sebagai birokrat yang menentukan kebijakan pendidikan atau penelitian yang berkaitan dengan ilmu kedokteran gigi.\r\n\r\nSebagai penutup, dengan bangga kami katakan bahwa PS MIKG Usakti merupakan salah satu program magister yang terbaik di negeri ini.  PS MIKG Usakti  mendapatkan akreditasi predikat “unggul” sejak tahun 2022 (SK Akreditasi 0289//LAM-PTKes/Akr/Mag/IV/2022). Kami mengundang Anda semua untuk bergabung dengan program kami dalam memajukan bidang kedokteran gigi. Terima kasih.', '2026-04-23 07:31:55', '2026-04-23 07:31:55'),
(14, 3, 'Program Pendidikan Dokter Gigi Spesialis Konservasi Gigi', 'program-pendidikan-dokter-gigi-spesialis-konservasi-gigi', 'Spesialis', 'image', '1776930045_a6d607b9cdba283815e2.jpeg', NULL, NULL, 'Dr. drg. Meiny Faudah Amin, Sp.KG., Subsp.KE(K)', '1776930045_a1229518e577dff3538d.png', 'Selamat datang di halaman website Program Studi Pendidikan Dokter Gigi Spesialis Konservasi Gigi kami.\r\n\r\nProgram Studi Pendidikan Dokter Gigi Spesialis Konservasi Gigi (PS PDGS KG) Fakultas Kedokteran Gigi Universitas Trisakti adalah satu-satunya program studi swasta di Indonesia dengan akreditasi unggul.\r\n\r\nProgram Studi ini didedikasikan untuk meningkatkan kebutuhan kesehatan masyarakat Indonesia dengan  menyediakan pendidikan mutakhir dalam bidang konservasi gigi. Kami berkomitmen untuk memberikan pendidikan yang terbaik  didukung oleh dosen dan staf yang berpengalaman, serta fasilitas terkini yang mendukung proses pembelajaran, dengan fokus microdentistry, seni-budaya melalui penelitian beretika serta kearifan lokal. Pendidikan di program ini menekankan pendekatan persuasif, penelitian, dan pengabdian kepada masyarakat untuk menghasilkan lulusan yang analitis, kritis, kreatif, dan siap menghadapi tantangan masa depan sebagai pemimpin. Kolaborasi dengan alumni, mitra pemerintah dan swasta, serta masyarakat, mendukung pengembangan sistem pendidikan yang terukur dan dievaluasi secara periodik.\r\n\r\nMari kita bersama berinovasi  dan berkontribusi membentuk generasi dokter gigi  spesialis konservasi gigi yang siap menghadapi tantangan masa depan. Selamat bergabung dengan kami di Program Studi Pendidikan Dokter Gigi Spesialis Konservasi Gigi FKG USAKTI. Terima kasih atas kunjungan Anda, dan semoga pengalaman Anda di halaman web ini membawa inspirasi.\r\n\r\nSalam hangat,\r\nDr. drg. Meiny Faudah Amin, Sp.KG., Subsp.KE(K)\r\nKepala Program Studi Pendidikan Dokter Gigi Spesialis Konservasi Gigi', '2026-04-23 07:36:13', '2026-04-23 07:40:45'),
(15, 3, 'Doktor Ilmu Kedokteran Gigi', 'doktor-ilmu-kedokteran-gigi', 'S3', 'image', '1776930330_b322583cfd2063c149c3.jpg', NULL, NULL, 'Prof. drg. Rahmi Amtha, M.D.S., Sp.PM., (K), PhD', '1776930330_fcc93aa776eeb8f1d3db.png', 'Yang saya hormati teman-teman sejawat,\r\n\r\nSelamat datang di Program Studi Doktor Ilmu Kedokteran Gigi, Fakultas Kedokteran Gigi, Universitas Trisakti.\r\n\r\nProgram Studi Doktor Ilmu Kedokteran Gigi di Fakultas Kedokteran Gigi Universitas Trisakti merupakan salah satu dari lima program studi yang ada di fakultas kami. Program studi ini telah resmi ditetapkan berdasarkan Surat Keputusan Direktorat Jenderal Pendidikan Tinggi Kementerian Pendidikan, Kebudayaan, Riset, dan Teknologi Republik Indonesia Nomor 678/E/O/2023 tanggal 21 Agustus 2023. Keputusan ini mengesahkan penyelenggaraan Program Studi Doktor di Universitas Trisakti, memperkuat komitmen kami dalam menyediakan pendidikan berkualitas di bidang kedokteran gigi.\r\n\r\nKebutuhan akan program studi S3 dalam bidang kedokteran gigi semakin mendesak seiring dengan meningkatnya jumlah institusi pendidikan dan tenaga pengajar di Indonesia. Program Doktor Ilmu Kedokteran Gigi merupakan jenjang pendidikan tertinggi yang harus ditempuh oleh seorang dosen sebagai pendidik profesional. Program ini juga menjadi program doktor pertama di bidang kedokteran gigi yang diselenggarakan oleh perguruan tinggi swasta di Indonesia, sebuah pencapaian yang sangat membanggakan bagi Universitas Trisakti.', '2026-04-23 07:45:30', '2026-04-23 07:45:30'),
(16, 4, 'Fotografi', 'fotografi', 'S1', 'image', '1776930553_cb93963bf45b521d5e81.jpg', 'Sebagai pelopor pendidikan tinggi fotografi di Indonesia, Universitas Trisakti bangga menjadi perguruan tinggi swasta pertama yang membuka Program Studi Fotografi jenjang S1. Hingga kini, Trisakti tetap menjadi satu-satunya institusi di Jakarta yang menyelenggarakan pendidikan fotografi S1 secara formal, dan telah terakreditasi A oleh BAN-PT, menjadikannya pusat pengembangan akademik dan profesionalisme dalam bidang fotografi.\r\n\r\nProgram ini dirancang dengan Kurikulum berbasis KKNI dan pendekatan Outcome-Based Education (OBE) yang berorientasi pada hasil dan kebutuhan dunia industri. Dengan beban studi sebanyak 144 SKS, mahasiswa memperoleh fondasi teoritis yang kuat sekaligus keterampilan praktis yang mutakhir, terutama dalam bidang fotografi komersial mulai dari Fashion Photography, Food and Product Photography, Photojournalism and Documentary, Architectural and Interior Photography, Urban and Street Photography hingga visual branding untuk media sosial.\r\n\r\nStruktur kurikulum yang seimbang antara teori dan praktik didukung oleh proses pembelajaran yang interaktif, baik di ruang kelas, studio, maupun melalui pengalaman langsung di lapangan. Mahasiswa juga didorong untuk memperluas wawasan melalui kuliah kerja lapangan, simulasi proyek industri, kerja sama lintas program studi, serta partisipasi dalam berbagai kegiatan seminar, pameran, kompetisi fotografi, dan program kolaboratif berskala nasional dan internasional.\r\n\r\nProgram ini tidak hanya mempersiapkan lulusan sebagai fotografer profesional, tetapi juga membangun visual thinking dan branding awareness, yang memiliki entrepreneurial mindset dengan  kepekaan estetik, serta kemampuan adaptif terhadap perkembangan teknologi dan industri fotografi. Pengalaman belajar diperkaya dengan berbagai kegiatan seperti seminar fotografi, pameran karya, kompetisi foto, hingga kolaborasi nasional dan internasional, menciptakan ekosistem belajar yang inspiratif dan kompetitif.', 'Program Studi Fotografi Universitas Trisakti didirikan berdasarkan Surat Keputusan Direktur Jenderal Pendidikan Tinggi Departemen Pendidikan dan Kebudayaan Republik Indonesia Nomor: 08/DIKTI/Kep./1996, yang menetapkan status terdaftar bagi program-program studi di lingkungan Fakultas Seni Rupa dan Desain.\r\n\r\nSejak berdirinya, program ini telah menunjukkan konsistensi dalam pengembangan pendidikan fotografi yang berkualitas dan pembaruan kurikulum serta peningkatan mutu akademik dan manajerial, Program Studi Fotografi kini telah terakreditasi “A” dari BAN-PT, dan telah mempertahankan status tersebut selama tiga periode berturut-turut.\r\n\r\nSelama lebih dari dua dekade perjalanannya, program ini telah meluluskan banyak fotografer profesional yang sukses di bidang fotografi komersial, serta entrepreneur muda yang mendirikan studio, agensi kreatif, dan bisnis visual berbasis teknologi digital. Kiprah para alumni ini memperkuat reputasi Program Studi Fotografi Trisakti sebagai institusi pendidikan yang tidak hanya unggul secara akademik, tetapi juga responsif terhadap perkembangan industri fotografi di tingkat nasional maupun global.', NULL, NULL, NULL, '2026-04-23 07:49:13', '2026-04-23 07:49:13'),
(17, 4, 'Magister Desain Produk', 'magister-desain-produk', 'S2', 'image', '1776930816_ac216373c730af53ed81.jpg', 'Program Studi Magister Desain Produk memiliki orientasi penyelenggaraan pendidikan yaitu mahasiswa diarahkan dalam membuat inovasi-inovasi dalam berkreasi, dengan didukung oleh pendalaman tanda-tanda dan system social yang berlaku di masyarakat (khususnya masyarakat urban) dan bagaimana seni dan desain dikomunikasikan, difungsikan, dimanfaatkan, dan diapresiasikan oleh masyarakat secara optimal. Proses kreatif seni dan desain pada tingkat magister merupakan pemecahan masalah yang mengandung dimensi sosial, dengan nilai-nilai lokal (local genius) sebagai identitas bangsa tetap terjaga dan dipertahankan. Sebagai Urban University, Universitas Trisakti adalah Perguruan Tinggi yang peduli terhadap permasalahan perkotaan, maka inovasi penciptaan seni dan desain harus mampu membentuk peradaban yang lebih baik, khususnya permasalahan-permasalah urban perkotaan. Pengutamaan Studi atau konsentrasi Program Studi Magister Desain, adalah pada: Desain Interior, Desain Komunikasi Visual, Desain Produk, dan Fotografi.', 'Atas anjuran Rektor Universitas Trisakti Prof. Dr. Thoby Mutis, ketika itu tahun 2006/2007 supaya dibentuk dan dibuka Pendidikan Tinggi Ilmu Seni Rupa dan Desain tingkat Strata 2 bidang Magister Desain (Master in Design).\r\n\r\nDalam rangka pengabdian kepada masyarakat, memenuhi hasrat mencapai ilmu yang mengglobal dan beragam, maka tahun ajaran 2006/2007 dibuka Program Magister Desain (Visual Art) di Universitas Trisakti yang di Ketuai oleh Prof. Yusuf Affendi D., MA lulusan Institut Teknologi Bandung dan lulusan USA Rochester Institut of Technology, New York.\r\n\r\nPada awalnya tahun pertama dan kedua, mahasiswanya berasal dari intern Universitas trisakti, sesudah tahun ketiga sampai sekarang di minati oleh mahasiswa yang berasal dari seluruh Indonesia, terutama dari Pulau jawa dan Pulau Sumatera. Demikian juga mahasiswa yang berasal dari Universitas-universitas di Eropa dan ASEAN seperti dari Jerman, Inggris dan Malaysia.\r\n\r\nIlmu Desain atau Visual Art yang berkembang pesat, serta dosen-dosen yang berasal dari Universitas kenamaan di dalam negeri maupun dosen yang berasal dari luar negeri menjadi daya tarik para mahasiswa untuk menempuh studi S2 Desain di Universitas Trisakti yang merupakan Perguruan Tinggi Swasta pertama yang memiliki Program  (S2) Magister Desain (Visual Art) di Indonesia.', NULL, NULL, NULL, '2026-04-23 07:53:36', '2026-04-23 07:53:36');

